// Gerado a partir de URNA01_V19_GLOBAL_AUTONOMA.ino, sem senhas e sem projetos.
// O site completa os campos {{...}} em gerador-urna.js.
window.MODELO_URNA = "\n#include <Wire.h>\n#include <LiquidCrystal_I2C.h>\n#include <Keypad.h>\n#include <Preferences.h>\n#include <WiFi.h>\n#include <WebServer.h>\n#include <HTTPClient.h>\n#include <WiFiClientSecure.h>\n#include <LittleFS.h>\n#include <freertos/FreeRTOS.h>\n#include <freertos/task.h>\n#include <freertos/semphr.h>\n\n// =====================================================\n// URNA PET UFPB - V19.1 MULTIURNA GLOBAL AUTONOMA\n// ESP32-C3 Mini + LCD 20x4 + Teclado 4x4\n//\n// FOCO DESTA VERSAO:\n// - Inicializacao autonoma sem depender de USB/Serial\n// - Controle GLOBAL compartilhado entre urna01, urna02 e site\n// - Zerar em uma urna cria uma nova rodada para TODO o sistema\n// - Encerrar/reabrir em uma urna vale para as DUAS urnas\n// - Antes de enviar dados apos reconexao, a urna confere o controle global\n// - Site ignora automaticamente dados de rodadas antigas\n// - Interface LCD reorganizada\n// - Menu operador paginado\n// - Telas de votacao mais limpas\n// - Ranking mais legivel\n// - Status Wi-Fi dividido em telas claras\n//\n// Mantem:\n// - votacao local\n// - persistencia em memoria\n// - desempate\n// - modo operador\n// - TOP 3\n// - totais\n// - encerrar/reabrir\n// - zerar com senha\n// - Wi-Fi robusto: STA OU AP, nunca simultaneos\n// - AP de configuracao somente manual ou sem credenciais\n// - reconexao STA automatica com maquina de estados\n// - evita WiFi.begin() repetido enquanto ainda conecta\n// - espera estabilizacao antes de sincronizar Firebase\n// - retry Firebase controlado apos falha/timeout\n// - avisos claros no Serial ao conectar/desconectar\n// - sincronizacao Firebase em tarefa de fundo\n// - teclado/LCD nao ficam bloqueados por HTTPS\n// - mutex para proteger fila offline e dados locais\n// - voto salvo localmente ANTES da sincronizacao\n// - fila offline persistente em LittleFS\n// - sincronizacao automatica com Firebase\n// - eventos com ID unico para evitar duplicacao\n// - ranking publico sem quantidade de votos\n// - Firebase Authentication por e-mail/senha\n// - ID token usado nas requisicoes REST\n// - renovacao automatica com refresh token\n// - UID conferido antes de sincronizar\n// - arquitetura multiurna com duas ESPs sem sobrescrever votos\n// - cada urna grava somente em seu proprio ramo no Firebase\n// - site soma os snapshots de urna01 e urna02\n// - eventos separados por ID de urna\n// - caminho definitivo multiurna: /urna/multiurna\n// - correcao de corrida entre LCD e tarefa Firebase apos o voto\n// - janela curta de protecao da interface antes de iniciar sincronizacao\n// =====================================================\n\n// ===================== LCD ===========================\n#define SDA_PIN 6\n#define SCL_PIN 7\n\nLiquidCrystal_I2C lcd(0x3F, 20, 4);\n\n// ===================== TECLADO =======================\nconst byte LINHAS = 4;\nconst byte COLUNAS = 4;\n\nchar teclas[LINHAS][COLUNAS] = {\n  {'1', '2', '3', 'A'},\n  {'4', '5', '6', 'B'},\n  {'7', '8', '9', 'C'},\n  {'*', '0', '#', 'D'}\n};\n\nbyte pinosLinhas[LINHAS] = {0, 1, 3, 4};\nbyte pinosColunas[COLUNAS] = {5, 10, 20, 21};\n\nKeypad teclado = Keypad(\n  makeKeymap(teclas),\n  pinosLinhas,\n  pinosColunas,\n  LINHAS,\n  COLUNAS\n);\n\n// ===================== MEMORIA =======================\nPreferences memoria;\n\n// ===================== WIFI ==========================\n// Arquitetura simples e robusta:\n//\n// 1) Se houver credenciais salvas, inicia SOMENTE como STA.\n// 2) Se conectar, permanece em STA.\n// 3) Se nao houver credenciais ou a conexao inicial falhar,\n//    muda para SOMENTE AP e abre a pagina de configuracao.\n// 4) Nunca usa AP + STA ao mesmo tempo.\n// 5) Ao salvar um novo Wi-Fi, reinicia e tenta a nova rede.\n//\n// O AP fica ABERTO (sem senha) somente durante a configuracao.\n// Isso foi escolhido porque o teste minimo do ESP32-C3 funcionou\n// de forma estavel nesse modo.\n\nWebServer servidor(80);\n\nconst char* NOME_AP = \"{{NOME_AP}}\";\n\nString wifiSSID = \"\";\nString wifiSenha = \"\";\n\nbool modoAPAtivo = false;\nbool servidorIniciado = false;\n\nbool reinicioAgendado = false;\nunsigned long momentoReinicio = 0;\n\n// ===================== ESTADO DA CONEXAO WIFI =====================\n// Evita chamar WiFi.begin() repetidamente enquanto o driver ainda\n// esta tentando associar. Cada tentativa tem inicio, tempo limite e\n// intervalo de espera bem definidos.\n\nenum EstadoWiFi {\n  WIFI_SEM_CREDENCIAIS,\n  WIFI_AP_CONFIGURACAO,\n  WIFI_DESCONECTADO,\n  WIFI_CONECTANDO,\n  WIFI_CONECTADO\n};\n\nEstadoWiFi estadoWiFi = WIFI_DESCONECTADO;\n\nunsigned long inicioTentativaWiFi = 0;\nunsigned long proximaTentativaWiFi = 0;\nunsigned long wifiConectadoDesde = 0;\n\nconst unsigned long TEMPO_MAX_TENTATIVA_WIFI = 15000;  // 15 s tentando\nconst unsigned long INTERVALO_RECONEXAO = 5000;        // 5 s entre tentativas\nconst unsigned long TEMPO_ESTABILIZACAO_WIFI = 5000;   // espera antes do Firebase\n\nbool wifiConexaoAnunciada = false;\nbool wifiEstabilizacaoAnunciada = false;\nbool firebaseConfirmadoNestaConexao = false;\n\n\n// ===================== FIREBASE / SINCRONIZACAO =====================\n//\n// V18 MULTIURNA: duas ESPs trabalhando no mesmo Firebase.\n//\n// TODAS as requisicoes usam Firebase Authentication + ID token.\n// Cada urna escreve SOMENTE no seu proprio ramo.\n//\n// Estrutura:\n// /urna/multiurna/eventos/<urna>/<id_unico>\n// /urna/multiurna/dispositivos/<urna>/projetos/...\n// /urna/multiurna/dispositivos/<urna>/ranking_local/...\n// /urna/multiurna/dispositivos/<urna>/status\n//\n// O site le os projetos de urna01 e urna02, soma os votos e calcula\n// o TOP 3 global. Eventos e status continuam privados.\n//\n// As regras finais devem:\n// - permitir escrita em /urna/multiurna somente para o UID autorizado;\n// - manter eventos/status/ranking_local privados;\n// - permitir leitura publica apenas dos dois ramos /projetos.\n\nconst char* FIREBASE_BASE =\n  \"https://fee20261-default-rtdb.firebaseio.com/urna/multiurna\";\n\n// Web API Key do projeto Firebase\nconst char* FIREBASE_API_KEY =\n  \"AIzaSyA27dn6kUmDD_AtaKixZsFK-zE2DMfETP4\";\n\n// UID autorizado para operar esta urna\nconst char* FIREBASE_UID_ESPERADO =\n  \"b2Ejyy4jJCYbx0edNZxB3QAnYuE2\";\n\n// Conta Firebase Authentication usada pela urna.\n// A senha deve ser preenchida LOCALMENTE no Arduino IDE.\nconst char* FIREBASE_EMAIL =\n  \"pet.eletrica@cear.ufpb.br\";\n\nconst char* FIREBASE_PASSWORD =\n  \"{{FIREBASE_PASSWORD}}\";\n\n// Tokens ficam apenas em RAM.\n// Ao reiniciar, a urna faz login novamente.\nString firebaseIdToken = \"\";\nString firebaseRefreshToken = \"\";\nString firebaseUIDAtual = \"\";\n\nbool firebaseAuthOK = false;\n\nunsigned long firebaseTokenObtidoEm = 0;\nunsigned long firebaseTokenValidadeUtilMs = 0;\n\n// Renova antes do vencimento real do ID token.\nconst unsigned long MARGEM_RENOVACAO_TOKEN_SEG = 300;\n\nconst char* ARQUIVO_PENDENTES = \"/pendentes.csv\";\nconst char* ARQUIVO_TEMP = \"/pendentes.tmp\";\n\nconst unsigned long INTERVALO_SYNC = 3500;\nconst unsigned long INTERVALO_RETRY_FIREBASE = 10000; // espera 10 s apos falha\n\nunsigned long ultimaTentativaSync = 0;\nunsigned long proximaTentativaFirebase = 0;\n\nbool littleFSOK = false;\nbool dadosSujos = true;\n\n// Identificador exclusivo desta ESP.\n// NAO use o mesmo ID nas duas urnas.\nconst char* ID_URNA = \"{{ID_URNA}}\";\n\n// ===================== CONTROLE GLOBAL MULTIURNA =====================\n//\n// O Firebase possui um unico estado oficial em:\n// /urna/multiurna/controle\n//\n// rodada_id:\n//   identifica a votacao atual. Ao \"zerar\", uma NOVA rodada e criada.\n//   Qualquer dado de rodada antiga deixa de valer imediatamente para o site.\n//\n// votacao_aberta:\n//   estado global compartilhado pelas duas urnas.\n//\n// IMPORTANTE:\n// - comandos administrativos globais exigem conexao com o Firebase;\n// - nenhuma urna envia snapshot/evento apos reconectar antes de conferir\n//   o controle global;\n// - isso impede que votos antigos \"ressuscitem\" depois de um reset.\n\nconst char* RODADA_INICIAL = \"R_INICIAL\";\n\nString rodadaLocal = RODADA_INICIAL;\nunsigned long contadorComandosGlobais = 0;\n\nbool controleGlobalConhecido = false;\nunsigned long ultimaConsultaControleGlobal = 0;\n\nconst unsigned long INTERVALO_CONTROLE_GLOBAL = 3000;\n\nenum TipoComandoGlobal {\n  CMD_GLOBAL_NENHUM = 0,\n  CMD_GLOBAL_ENCERRAR = 1,\n  CMD_GLOBAL_REABRIR = 2,\n  CMD_GLOBAL_ZERAR = 3\n};\n\nvolatile int comandoGlobalPendente = CMD_GLOBAL_NENHUM;\nvolatile int resultadoComandoGlobal = 0; // 0=aguardando, 1=OK, -1=erro\nvolatile int comandoGlobalUIAtual = CMD_GLOBAL_NENHUM;\nvolatile bool aguardandoComandoGlobalUI = false;\nvolatile bool atualizarInterfacePorControleGlobal = false;\n\nstruct VotoPendente {\n  String id;\n  byte curso;\n  byte numero;\n  unsigned long sequencia;\n  unsigned long votosDepois;\n  unsigned long ordemAtingida;\n};\n\n// ===================== CONCORRENCIA / BACKGROUND =====================\n// A ESP32-C3 possui um unico nucleo, mas o FreeRTOS alterna as tarefas.\n// O HTTPS roda em uma tarefa separada para nao bloquear o loop que le\n// teclado e atualiza o LCD.\n\nSemaphoreHandle_t mutexFila = nullptr;\nSemaphoreHandle_t mutexDados = nullptr;\nTaskHandle_t tarefaFirebaseHandle = nullptr;\n\n// Incrementa sempre que votos/estado local mudam.\n// Evita marcar um snapshot como \"limpo\" se houve um novo voto enquanto\n// a requisicao HTTPS estava em andamento.\nvolatile unsigned long geracaoDados = 0;\n\n// Protege a atualizacao visual do LCD.\n// A tarefa Firebase respeita esta janela antes de iniciar HTTPS.\nvolatile bool interfaceAtualizando = false;\nvolatile unsigned long liberarSyncApos = 0;\n\nconst unsigned long TEMPO_PROTECAO_LCD_APOS_TELA = 1200;\n\n// Declaracoes antecipadas usadas pela camada de sincronizacao.\nstruct Projeto;\nProjeto* buscarProjeto(byte curso, int numero);\n\n\n// ===================== PROJETOS ======================\nstruct Projeto {\n  byte numero;\n  const char* nome;\n  unsigned long votos;\n  unsigned long ordemAtingida;\n};\n\n// ================= ENGENHARIA ELETRICA - A ===========\nProjeto eletrica[] = {\n{{PROJETOS_ELETRICA}}\n};\n\nconst int TOTAL_ELETRICA = sizeof(eletrica) / sizeof(eletrica[0]);\n\n// ============== ENERGIAS RENOVAVEIS - B =============\nProjeto renovaveis[] = {\n{{PROJETOS_RENOVAVEIS}}\n};\nconst int TOTAL_RENOVAVEIS = sizeof(renovaveis) / sizeof(renovaveis[0]);\n\n// ===================== ESTADOS ========================\nenum Estado {\n  TELA_INICIAL,\n  DIGITAR_PROJETO,\n  CONFIRMAR_VOTO,\n  SENHA_OPERADOR,\n  MENU_OPERADOR,\n  RESULTADO_NAVEGAVEL,\n  STATUS_WIFI,\n  SENHA_ZERAR,\n  CONFIRMAR_ENCERRAR,\n  CONFIRMAR_REABRIR,\n  CONFIRMAR_ZERAR\n};\n\nvolatile Estado estado = TELA_INICIAL;\n\n// ===================== VARIAVEIS ======================\nbyte cursoSelecionado = 0;\nString numeroDigitado = \"\";\nProjeto* projetoSelecionado = nullptr;\n\nunsigned long sequenciaGlobal = 0;\nbool votacaoAberta = true;\n\nString senhaOperador = \"{{SENHA_OPERADOR}}\";\nString senhaDigitada = \"\";\n\nProjeto* rankingAtual[50];\nint quantidadeRanking = 0;\nint indiceRanking = 0;\nbyte cursoRanking = 0;\n\nbyte paginaMenuOperador = 1;\nbyte paginaStatusWiFi = 1;\n\n// ===================== LCD ============================\nvoid limparLinha(byte linha) {\n  lcd.setCursor(0, linha);\n  lcd.print(\"                    \");\n}\n\nvoid escreverLinha(byte linha, String texto) {\n  limparLinha(linha);\n  lcd.setCursor(0, linha);\n\n  if (texto.length() > 20) {\n    texto = texto.substring(0, 20);\n  }\n\n  lcd.print(texto);\n}\n\nString limitarTexto(String texto, byte limite = 20) {\n  if (texto.length() > limite) {\n    return texto.substring(0, limite);\n  }\n  return texto;\n}\n\n// =====================================================\n// WIFI - FUNCOES\n// =====================================================\n\nvoid carregarCredenciaisWiFi() {\n  memoria.begin(\"wifi\", true);\n  wifiSSID = memoria.getString(\"ssid\", \"\");\n  wifiSenha = memoria.getString(\"senha\", \"\");\n  memoria.end();\n}\n\nvoid salvarCredenciaisWiFi(const String& ssid, const String& senha) {\n  memoria.begin(\"wifi\", false);\n  memoria.putString(\"ssid\", ssid);\n  memoria.putString(\"senha\", senha);\n  memoria.end();\n\n  wifiSSID = ssid;\n  wifiSenha = senha;\n}\n\nString paginaConfiguracaoWiFi(String mensagem = \"\") {\n  String html;\n  html.reserve(3000);\n\n  html += \"<!DOCTYPE html><html lang='pt-BR'><head>\";\n  html += \"<meta charset='UTF-8'>\";\n  html += \"<meta name='viewport' content='width=device-width,initial-scale=1'>\";\n  html += \"<title>Urna PET - Wi-Fi</title>\";\n  html += \"<style>\";\n  html += \"body{font-family:Arial,sans-serif;background:#f3f5f7;padding:18px;}\";\n  html += \".box{max-width:430px;margin:auto;background:white;padding:24px;\";\n  html += \"border-radius:14px;box-shadow:0 4px 18px #0002;}\";\n  html += \"h2{margin-top:0}\";\n  html += \"input{width:100%;padding:12px;margin:7px 0 15px;\";\n  html += \"box-sizing:border-box;border:1px solid #bbb;border-radius:8px;}\";\n  html += \"button{width:100%;padding:13px;font-size:16px;border:0;\";\n  html += \"border-radius:8px;cursor:pointer;}\";\n  html += \".msg{padding:11px;background:#eef2f5;border-radius:8px;\";\n  html += \"margin-bottom:15px;}\";\n  html += \".aviso{font-size:13px;margin-top:18px;color:#555;}\";\n  html += \"</style></head><body><div class='box'>\";\n\n  html += \"<h2>Urna PET UFPB</h2>\";\n  html += \"<p><b>Configuracao de Wi-Fi</b></p>\";\n\n  if (mensagem.length() > 0) {\n    html += \"<div class='msg'>\" + mensagem + \"</div>\";\n  }\n\n  html += \"<form method='POST' action='/salvar'>\";\n  html += \"<label>Nome da rede (SSID)</label>\";\n  html += \"<input name='ssid' maxlength='32' autocomplete='off' required>\";\n  html += \"<label>Senha da rede</label>\";\n  html += \"<input name='senha' type='password' maxlength='64'>\";\n  html += \"<button type='submit'>Salvar Wi-Fi</button>\";\n  html += \"</form>\";\n\n  html += \"<p class='aviso'>\";\n  html += \"Depois de salvar, a urna reinicia automaticamente e tenta conectar. \";\n  html += \"A votacao e os votos salvos nao sao apagados.\";\n  html += \"</p>\";\n\n  html += \"</div></body></html>\";\n\n  return html;\n}\n\nvoid configurarServidorWeb() {\n  if (servidorIniciado) return;\n\n  servidor.on(\"/\", HTTP_GET, []() {\n    servidor.send(\n      200,\n      \"text/html; charset=utf-8\",\n      paginaConfiguracaoWiFi()\n    );\n  });\n\n  servidor.on(\"/salvar\", HTTP_POST, []() {\n    if (!servidor.hasArg(\"ssid\")) {\n      servidor.send(\n        400,\n        \"text/html; charset=utf-8\",\n        paginaConfiguracaoWiFi(\"SSID nao informado.\")\n      );\n      return;\n    }\n\n    String novoSSID = servidor.arg(\"ssid\");\n    String novaSenha = servidor.arg(\"senha\");\n\n    novoSSID.trim();\n\n    if (novoSSID.length() == 0) {\n      servidor.send(\n        400,\n        \"text/html; charset=utf-8\",\n        paginaConfiguracaoWiFi(\"SSID invalido.\")\n      );\n      return;\n    }\n\n    salvarCredenciaisWiFi(novoSSID, novaSenha);\n\n    servidor.send(\n      200,\n      \"text/html; charset=utf-8\",\n      paginaConfiguracaoWiFi(\n        \"Wi-Fi salvo com sucesso. A urna vai reiniciar em alguns segundos.\"\n      )\n    );\n\n    // Nao muda de AP para STA no meio da requisicao.\n    // Salva primeiro e reinicia de forma limpa.\n    reinicioAgendado = true;\n    momentoReinicio = millis();\n  });\n\n  servidor.onNotFound([]() {\n    // Facilita abrir a pagina mesmo digitando outro endereco.\n    servidor.sendHeader(\"Location\", \"/\", true);\n    servidor.send(302, \"text/plain\", \"\");\n  });\n\n  servidor.begin();\n  servidorIniciado = true;\n\n  Serial.println(\"Servidor de configuracao iniciado.\");\n}\n\nvoid iniciarModoConfiguracaoAP() {\n  Serial.println();\n  Serial.println(\"Entrando no modo de configuracao AP...\");\n\n  // Desliga completamente o modo anterior antes de criar o AP.\n  // Evita misturar STA e AP na mesma sessao.\n  WiFi.disconnect(true, false);\n  delay(300);\n\n  WiFi.mode(WIFI_OFF);\n  delay(200);\n\n  WiFi.mode(WIFI_AP);\n  delay(300);\n\n  // Mesmo formato que funcionou no teste minimo:\n  // AP aberto, canal 6, SSID visivel, ate 4 clientes.\n  bool ok = WiFi.softAP(\n    NOME_AP,\n    NULL,\n    6,\n    0,\n    4\n  );\n\n  if (ok) {\n    modoAPAtivo = true;\n    estadoWiFi = WIFI_AP_CONFIGURACAO;\n    wifiConectadoDesde = 0;\n    wifiConexaoAnunciada = false;\n    firebaseConfirmadoNestaConexao = false;\n\n    configurarServidorWeb();\n\n    Serial.println(\"=== CONFIGURACAO WIFI ATIVA ===\");\n    Serial.print(\"Rede: \");\n    Serial.println(NOME_AP);\n    Serial.println(\"Senha: nenhuma (rede aberta)\");\n    Serial.print(\"IP: \");\n    Serial.println(WiFi.softAPIP());\n  } else {\n    modoAPAtivo = false;\n    estadoWiFi = WIFI_DESCONECTADO;\n    Serial.println(\"ERRO: nao foi possivel iniciar o AP.\");\n  }\n}\n\nvoid anunciarWiFiConectado() {\n  if (wifiConexaoAnunciada) return;\n\n  wifiConexaoAnunciada = true;\n  wifiEstabilizacaoAnunciada = false;\n  wifiConectadoDesde = millis();\n  firebaseConfirmadoNestaConexao = false;\n\n  // Antes de qualquer envio nesta nova conexao,\n  // sera obrigatorio reler o controle global.\n  controleGlobalConhecido = false;\n  ultimaConsultaControleGlobal = 0;\n\n  Serial.println();\n  Serial.println(\"========================================\");\n  Serial.println(\"=== WIFI CONECTADO COM SUCESSO! =======\");\n  Serial.println(\"========================================\");\n  Serial.print(\"SSID: \");\n  Serial.println(WiFi.SSID());\n  Serial.print(\"IP: \");\n  Serial.println(WiFi.localIP());\n  Serial.print(\"Sinal: \");\n  Serial.print(WiFi.RSSI());\n  Serial.println(\" dBm\");\n  Serial.println(\"Aguardando estabilizacao antes do Firebase...\");\n  Serial.println();\n}\n\nvoid iniciarTentativaSTA() {\n  if (modoAPAtivo) return;\n  if (wifiSSID.length() == 0) return;\n  if (estadoWiFi == WIFI_CONECTANDO) return;\n  if (WiFi.status() == WL_CONNECTED) {\n    estadoWiFi = WIFI_CONECTADO;\n    anunciarWiFiConectado();\n    return;\n  }\n\n  Serial.println();\n  Serial.println(\"Wi-Fi offline. Iniciando tentativa de reconexao...\");\n  Serial.print(\"SSID: \");\n  Serial.println(wifiSSID);\n\n  // Configura STA somente quando inicia uma NOVA tentativa.\n  WiFi.mode(WIFI_STA);\n  WiFi.disconnect(false, false);\n  delay(80);\n\n  WiFi.begin(\n    wifiSSID.c_str(),\n    wifiSenha.c_str()\n  );\n\n  inicioTentativaWiFi = millis();\n  estadoWiFi = WIFI_CONECTANDO;\n}\n\nvoid iniciarSistemaWiFi() {\n  carregarCredenciaisWiFi();\n\n  // Sem credenciais: AP apenas para configuracao inicial.\n  if (wifiSSID.length() == 0) {\n    estadoWiFi = WIFI_SEM_CREDENCIAIS;\n    iniciarModoConfiguracaoAP();\n    return;\n  }\n\n  // Com credenciais, a urna fica SEMPRE em STA durante a votacao.\n  // Nao cai automaticamente para AP se a rede estiver indisponivel.\n  modoAPAtivo = false;\n\n  WiFi.disconnect(true, false);\n  delay(250);\n\n  WiFi.mode(WIFI_OFF);\n  delay(150);\n\n  WiFi.mode(WIFI_STA);\n  delay(150);\n\n  estadoWiFi = WIFI_DESCONECTADO;\n  proximaTentativaWiFi = millis();\n\n  Serial.println();\n  Serial.println(\"Wi-Fi salvo carregado.\");\n  Serial.print(\"SSID: \");\n  Serial.println(wifiSSID);\n  Serial.println(\"A urna tentara reconectar automaticamente ate conseguir.\");\n\n  iniciarTentativaSTA();\n}\n\nvoid gerenciarWiFi() {\n  if (modoAPAtivo) {\n    servidor.handleClient();\n\n    // Reinicio limpo depois que a pagina terminou de responder.\n    if (\n      reinicioAgendado &&\n      millis() - momentoReinicio >= 1800\n    ) {\n      Serial.println(\"Reiniciando para aplicar o novo Wi-Fi...\");\n      delay(100);\n      ESP.restart();\n    }\n\n    return;\n  }\n\n  wl_status_t statusAtual = WiFi.status();\n\n  // Detecta conexao concluida, inclusive se aconteceu entre iteracoes.\n  if (statusAtual == WL_CONNECTED) {\n    if (estadoWiFi != WIFI_CONECTADO) {\n      estadoWiFi = WIFI_CONECTADO;\n      anunciarWiFiConectado();\n\n      // Primeira tentativa Firebase somente depois do periodo de estabilidade.\n      proximaTentativaFirebase =\n        millis() + TEMPO_ESTABILIZACAO_WIFI;\n    }\n\n    // Avisa explicitamente quando os 5 segundos de estabilizacao terminarem.\n    // Esta mensagem aparece apenas uma vez por conexao/reconexao.\n    if (\n      !wifiEstabilizacaoAnunciada &&\n      wifiConectadoDesde > 0 &&\n      millis() - wifiConectadoDesde >= TEMPO_ESTABILIZACAO_WIFI\n    ) {\n      wifiEstabilizacaoAnunciada = true;\n\n      int pendentesAgora = contarPendentes();\n\n      Serial.println();\n      Serial.println(\"========================================\");\n      Serial.println(\"=== WIFI ESTABILIZADO ==================\");\n      Serial.println(\"Conexao pronta para sincronizacao.\");\n      Serial.print(\"Pendentes na fila: \");\n      Serial.println(pendentesAgora);\n\n      if (pendentesAgora > 0) {\n        Serial.println(\"Firebase: autenticacao + sync serao iniciadas em background.\");\n      } else if (dadosSujos) {\n        Serial.println(\"Firebase: autenticacao + atualizacao aguardando.\");\n      } else {\n        Serial.println(\"Firebase: nenhum dado pendente no momento.\");\n      }\n\n      Serial.println(\"========================================\");\n      Serial.println();\n    }\n\n    return;\n  }\n\n  // Detecta queda depois de uma conexao que estava ativa.\n  if (estadoWiFi == WIFI_CONECTADO) {\n    Serial.println();\n    Serial.println(\"========================================\");\n    Serial.println(\"=== WIFI DESCONECTADO ==================\");\n    Serial.println(\"A votacao continua funcionando offline.\");\n    Serial.println(\"Os votos ficarao pendentes e serao enviados\");\n    Serial.println(\"automaticamente quando a rede voltar.\");\n    Serial.println(\"========================================\");\n\n    wifiConexaoAnunciada = false;\n    wifiEstabilizacaoAnunciada = false;\n    wifiConectadoDesde = 0;\n    firebaseConfirmadoNestaConexao = false;\n    controleGlobalConhecido = false;\n    ultimaConsultaControleGlobal = 0;\n\n    estadoWiFi = WIFI_DESCONECTADO;\n    proximaTentativaWiFi = millis() + 1000;\n    return;\n  }\n\n  // Uma tentativa ja esta em andamento: NAO chama WiFi.begin() de novo.\n  if (estadoWiFi == WIFI_CONECTANDO) {\n    if (\n      millis() - inicioTentativaWiFi >=\n      TEMPO_MAX_TENTATIVA_WIFI\n    ) {\n      Serial.println();\n      Serial.println(\"Tentativa Wi-Fi expirou.\");\n      Serial.print(\"Status atual: \");\n      Serial.println((int)WiFi.status());\n      Serial.println(\"Aguardando antes da proxima tentativa...\");\n\n      WiFi.disconnect(false, false);\n\n      estadoWiFi = WIFI_DESCONECTADO;\n      proximaTentativaWiFi =\n        millis() + INTERVALO_RECONEXAO;\n    }\n\n    return;\n  }\n\n  // Desconectado e fora de tentativa: aguarda o proximo horario.\n  if (\n    estadoWiFi == WIFI_DESCONECTADO &&\n    millis() >= proximaTentativaWiFi\n  ) {\n    iniciarTentativaSTA();\n  }\n\n  // Reinicio agendado normalmente so ocorre no AP, mas fica seguro aqui.\n  if (\n    reinicioAgendado &&\n    millis() - momentoReinicio >= 1800\n  ) {\n    Serial.println(\"Reiniciando para aplicar o novo Wi-Fi...\");\n    delay(100);\n    ESP.restart();\n  }\n}\n\n// ===================== MEMORIA URNA ==================\nString chaveVotos(byte curso, byte numero) {\n  return String(curso == 1 ? \"A\" : \"B\") + String(numero);\n}\n\nString chaveOrdem(byte curso, byte numero) {\n  return String(\"O\") + String(curso == 1 ? \"A\" : \"B\") + String(numero);\n}\n\nvoid salvarEstadoGeral() {\n  memoria.begin(\"urna\", false);\n  memoria.putULong(\"sequencia\", sequenciaGlobal);\n  memoria.putBool(\"aberta\", votacaoAberta);\n  memoria.putBool(\"dirty\", dadosSujos);\n  memoria.putString(\"rodada\", rodadaLocal);\n  memoria.putULong(\"cmdseq\", contadorComandosGlobais);\n  memoria.end();\n}\n\nvoid salvarProjeto(byte curso, Projeto* projeto) {\n  memoria.begin(\"urna\", false);\n\n  String chaveV = chaveVotos(curso, projeto->numero);\n  String chaveO = chaveOrdem(curso, projeto->numero);\n\n  memoria.putULong(chaveV.c_str(), projeto->votos);\n  memoria.putULong(chaveO.c_str(), projeto->ordemAtingida);\n  memoria.putULong(\"sequencia\", sequenciaGlobal);\n  memoria.putBool(\"aberta\", votacaoAberta);\n\n  memoria.end();\n}\n\nvoid carregarMemoria() {\n  memoria.begin(\"urna\", true);\n\n  sequenciaGlobal = memoria.getULong(\"sequencia\", 0);\n  votacaoAberta = memoria.getBool(\"aberta\", true);\n  rodadaLocal = memoria.getString(\"rodada\", RODADA_INICIAL);\n  contadorComandosGlobais = memoria.getULong(\"cmdseq\", 0);\n\n  // Se a chave ainda nao existir (primeira execucao desta versao),\n  // inicia como \"sujo\" para publicar um snapshot completo.\n  dadosSujos = memoria.getBool(\"dirty\", true);\n\n  for (int i = 0; i < TOTAL_ELETRICA; i++) {\n    String chaveV = chaveVotos(1, eletrica[i].numero);\n    String chaveO = chaveOrdem(1, eletrica[i].numero);\n\n    eletrica[i].votos = memoria.getULong(chaveV.c_str(), 0);\n    eletrica[i].ordemAtingida = memoria.getULong(chaveO.c_str(), 0);\n  }\n\n  for (int i = 0; i < TOTAL_RENOVAVEIS; i++) {\n    String chaveV = chaveVotos(2, renovaveis[i].numero);\n    String chaveO = chaveOrdem(2, renovaveis[i].numero);\n\n    renovaveis[i].votos = memoria.getULong(chaveV.c_str(), 0);\n    renovaveis[i].ordemAtingida = memoria.getULong(chaveO.c_str(), 0);\n  }\n\n  memoria.end();\n}\n\n\n// =====================================================\n// FILA OFFLINE / LITTLEFS\n// =====================================================\n\nbool iniciarLittleFS() {\n  if (LittleFS.begin(false)) {\n    littleFSOK = true;\n    return true;\n  }\n\n  Serial.println(\"LittleFS: falha ao montar. Tentando formatar...\");\n  if (LittleFS.begin(true)) {\n    littleFSOK = true;\n    Serial.println(\"LittleFS: formatado e montado.\");\n    return true;\n  }\n\n  littleFSOK = false;\n  Serial.println(\"ERRO: LittleFS indisponivel.\");\n  return false;\n}\n\nvoid salvarDirty(bool valor) {\n  dadosSujos = valor;\n\n  memoria.begin(\"urna\", false);\n  memoria.putBool(\"dirty\", valor);\n  memoria.end();\n}\n\nString criarIdVoto(unsigned long seq) {\n  return String(ID_URNA) + \"_\" + String(seq);\n}\n\nint contarPendentes() {\n  if (!littleFSOK) return 0;\n\n  if (mutexFila) {\n    xSemaphoreTake(mutexFila, portMAX_DELAY);\n  }\n\n  int total = 0;\n\n  if (LittleFS.exists(ARQUIVO_PENDENTES)) {\n    File f = LittleFS.open(ARQUIVO_PENDENTES, \"r\");\n\n    if (f) {\n      while (f.available()) {\n        String linha = f.readStringUntil('\\n');\n        linha.trim();\n\n        if (linha.length() > 0) {\n          total++;\n        }\n      }\n\n      f.close();\n    }\n  }\n\n  if (mutexFila) {\n    xSemaphoreGive(mutexFila);\n  }\n\n  return total;\n}\n\nbool adicionarPendente(\n  const String& id,\n  byte curso,\n  byte numero,\n  unsigned long sequencia,\n  unsigned long votosDepois,\n  unsigned long ordemAtingida\n) {\n  if (!littleFSOK) {\n    Serial.println(\"AVISO: voto salvo localmente, mas LittleFS indisponivel.\");\n    return false;\n  }\n\n  if (mutexFila) {\n    xSemaphoreTake(mutexFila, portMAX_DELAY);\n  }\n\n  File f = LittleFS.open(ARQUIVO_PENDENTES, \"a\");\n\n  if (!f) {\n    if (mutexFila) {\n      xSemaphoreGive(mutexFila);\n    }\n\n    Serial.println(\"ERRO: nao foi possivel abrir fila pendente.\");\n    return false;\n  }\n\n  // CSV simples:\n  // id,curso,numero,sequencia,votosDepois,ordemAtingida\n  f.print(id);\n  f.print(\",\");\n  f.print(curso);\n  f.print(\",\");\n  f.print(numero);\n  f.print(\",\");\n  f.print(sequencia);\n  f.print(\",\");\n  f.print(votosDepois);\n  f.print(\",\");\n  f.println(ordemAtingida);\n\n  f.flush();\n  f.close();\n\n  if (mutexFila) {\n    xSemaphoreGive(mutexFila);\n  }\n\n  Serial.print(\"Voto colocado na fila offline: \");\n  Serial.println(id);\n\n  return true;\n}\n\nbool parseLinhaPendente(const String& linhaOriginal, VotoPendente& voto) {\n  String linha = linhaOriginal;\n  linha.trim();\n\n  if (linha.length() == 0) return false;\n\n  int p1 = linha.indexOf(',');\n  int p2 = linha.indexOf(',', p1 + 1);\n  int p3 = linha.indexOf(',', p2 + 1);\n  int p4 = linha.indexOf(',', p3 + 1);\n  int p5 = linha.indexOf(',', p4 + 1);\n\n  if (\n    p1 < 0 || p2 < 0 || p3 < 0 ||\n    p4 < 0 || p5 < 0\n  ) {\n    return false;\n  }\n\n  voto.id = linha.substring(0, p1);\n  voto.curso = (byte) linha.substring(p1 + 1, p2).toInt();\n  voto.numero = (byte) linha.substring(p2 + 1, p3).toInt();\n  voto.sequencia = strtoul(\n    linha.substring(p3 + 1, p4).c_str(),\n    nullptr,\n    10\n  );\n  voto.votosDepois = strtoul(\n    linha.substring(p4 + 1, p5).c_str(),\n    nullptr,\n    10\n  );\n  voto.ordemAtingida = strtoul(\n    linha.substring(p5 + 1).c_str(),\n    nullptr,\n    10\n  );\n\n  return true;\n}\n\nbool lerPrimeiroPendente(VotoPendente& voto) {\n  if (!littleFSOK) return false;\n\n  if (mutexFila) {\n    xSemaphoreTake(mutexFila, portMAX_DELAY);\n  }\n\n  bool encontrou = false;\n\n  if (LittleFS.exists(ARQUIVO_PENDENTES)) {\n    File f = LittleFS.open(ARQUIVO_PENDENTES, \"r\");\n\n    if (f) {\n      while (f.available()) {\n        String linha = f.readStringUntil('\\n');\n\n        if (parseLinhaPendente(linha, voto)) {\n          encontrou = true;\n          break;\n        }\n      }\n\n      f.close();\n    }\n  }\n\n  if (mutexFila) {\n    xSemaphoreGive(mutexFila);\n  }\n\n  return encontrou;\n}\n\nbool removerPrimeiroPendente() {\n  if (!littleFSOK) return false;\n\n  if (mutexFila) {\n    xSemaphoreTake(mutexFila, portMAX_DELAY);\n  }\n\n  if (!LittleFS.exists(ARQUIVO_PENDENTES)) {\n    if (mutexFila) {\n      xSemaphoreGive(mutexFila);\n    }\n    return true;\n  }\n\n  File origem = LittleFS.open(ARQUIVO_PENDENTES, \"r\");\n\n  if (!origem) {\n    if (mutexFila) {\n      xSemaphoreGive(mutexFila);\n    }\n    return false;\n  }\n\n  File destino = LittleFS.open(ARQUIVO_TEMP, \"w\");\n\n  if (!destino) {\n    origem.close();\n\n    if (mutexFila) {\n      xSemaphoreGive(mutexFila);\n    }\n\n    return false;\n  }\n\n  bool primeiroValidoIgnorado = false;\n\n  while (origem.available()) {\n    String linha = origem.readStringUntil('\\n');\n    String teste = linha;\n    teste.trim();\n\n    if (!primeiroValidoIgnorado && teste.length() > 0) {\n      primeiroValidoIgnorado = true;\n      continue;\n    }\n\n    if (teste.length() > 0) {\n      destino.println(teste);\n    }\n  }\n\n  origem.close();\n  destino.flush();\n  destino.close();\n\n  LittleFS.remove(ARQUIVO_PENDENTES);\n\n  bool ok = LittleFS.rename(\n    ARQUIVO_TEMP,\n    ARQUIVO_PENDENTES\n  );\n\n  if (mutexFila) {\n    xSemaphoreGive(mutexFila);\n  }\n\n  if (!ok) {\n    Serial.println(\"ERRO: falha ao atualizar fila pendente.\");\n    return false;\n  }\n\n  return true;\n}\n\nvoid limparFilaPendentes() {\n  if (!littleFSOK) return;\n\n  if (mutexFila) {\n    xSemaphoreTake(mutexFila, portMAX_DELAY);\n  }\n\n  if (LittleFS.exists(ARQUIVO_PENDENTES)) {\n    LittleFS.remove(ARQUIVO_PENDENTES);\n  }\n\n  if (LittleFS.exists(ARQUIVO_TEMP)) {\n    LittleFS.remove(ARQUIVO_TEMP);\n  }\n\n  if (mutexFila) {\n    xSemaphoreGive(mutexFila);\n  }\n}\n\n// =====================================================\n// FIREBASE REST\n// =====================================================\n\nString escaparJSON(const String& texto) {\n  String saida;\n  saida.reserve(texto.length() + 8);\n\n  for (size_t i = 0; i < texto.length(); i++) {\n    char c = texto[i];\n\n    if (c == '\\\\') {\n      saida += \"\\\\\\\\\";\n    }\n    else if (c == '\"') {\n      saida += \"\\\\\\\"\";\n    }\n    else if (c == '\\n' || c == '\\r') {\n      saida += ' ';\n    }\n    else {\n      saida += c;\n    }\n  }\n\n  return saida;\n}\n\n\nString extrairStringJSONAuth(\n  const String& json,\n  const String& chave\n) {\n  String marcador = \"\\\"\" + chave + \"\\\"\";\n\n  int pos = json.indexOf(marcador);\n\n  if (pos < 0) {\n    return \"\";\n  }\n\n  pos += marcador.length();\n\n  while (\n    pos < json.length() &&\n    isspace((unsigned char) json[pos])\n  ) {\n    pos++;\n  }\n\n  if (\n    pos >= json.length() ||\n    json[pos] != ':'\n  ) {\n    return \"\";\n  }\n\n  pos++;\n\n  while (\n    pos < json.length() &&\n    isspace((unsigned char) json[pos])\n  ) {\n    pos++;\n  }\n\n  if (\n    pos >= json.length() ||\n    json[pos] != '\"'\n  ) {\n    return \"\";\n  }\n\n  pos++;\n\n  String valor;\n  bool escape = false;\n\n  for (; pos < json.length(); pos++) {\n    char c = json[pos];\n\n    if (escape) {\n      switch (c) {\n        case '\"':  valor += '\"';  break;\n        case '\\\\': valor += '\\\\'; break;\n        case '/':  valor += '/';  break;\n        case 'n':  valor += '\\n'; break;\n        case 'r':  valor += '\\r'; break;\n        case 't':  valor += '\\t'; break;\n        default:   valor += c;    break;\n      }\n\n      escape = false;\n      continue;\n    }\n\n    if (c == '\\\\') {\n      escape = true;\n      continue;\n    }\n\n    if (c == '\"') {\n      return valor;\n    }\n\n    valor += c;\n  }\n\n  return \"\";\n}\n\nString urlEncodeAuth(const String& texto) {\n  const char* hex = \"0123456789ABCDEF\";\n  String saida;\n  saida.reserve(texto.length() * 2);\n\n  for (size_t i = 0; i < texto.length(); i++) {\n    unsigned char c = (unsigned char) texto[i];\n\n    if (\n      (c >= 'a' && c <= 'z') ||\n      (c >= 'A' && c <= 'Z') ||\n      (c >= '0' && c <= '9') ||\n      c == '-' || c == '_' ||\n      c == '.' || c == '~'\n    ) {\n      saida += (char) c;\n    }\n    else {\n      saida += '%';\n      saida += hex[(c >> 4) & 0x0F];\n      saida += hex[c & 0x0F];\n    }\n  }\n\n  return saida;\n}\n\nvoid invalidarFirebaseAuth() {\n  firebaseAuthOK = false;\n  firebaseIdToken = \"\";\n  firebaseTokenObtidoEm = 0;\n  firebaseTokenValidadeUtilMs = 0;\n}\n\nvoid configurarValidadeToken(\n  const String& expiresIn\n) {\n  unsigned long segundos =\n    strtoul(expiresIn.c_str(), nullptr, 10);\n\n  if (segundos == 0) {\n    segundos = 3600;\n  }\n\n  unsigned long margem =\n    MARGEM_RENOVACAO_TOKEN_SEG;\n\n  if (segundos <= margem + 60) {\n    margem = 60;\n  }\n\n  unsigned long segundosUteis =\n    segundos > margem\n      ? segundos - margem\n      : segundos;\n\n  firebaseTokenObtidoEm = millis();\n\n  firebaseTokenValidadeUtilMs =\n    segundosUteis * 1000UL;\n}\n\nbool firebaseTokenPrecisaRenovar() {\n  if (!firebaseAuthOK) return true;\n  if (firebaseIdToken.length() == 0) return true;\n  if (firebaseTokenValidadeUtilMs == 0) return true;\n\n  return (\n    millis() - firebaseTokenObtidoEm >=\n    firebaseTokenValidadeUtilMs\n  );\n}\n\nbool loginFirebaseAuth() {\n  if (\n    String(FIREBASE_PASSWORD) ==\n    \"COLOQUE_A_SENHA_AQUI\"\n  ) {\n    Serial.println();\n    Serial.println(\"========================================\");\n    Serial.println(\"ERRO FIREBASE AUTH:\");\n    Serial.println(\"Preencha FIREBASE_PASSWORD no codigo.\");\n    Serial.println(\"A votacao continua funcionando offline.\");\n    Serial.println(\"========================================\");\n\n    invalidarFirebaseAuth();\n    return false;\n  }\n\n  if (WiFi.status() != WL_CONNECTED) {\n    return false;\n  }\n\n  String url =\n    \"https://identitytoolkit.googleapis.com/\"\n    \"v1/accounts:signInWithPassword?key=\";\n\n  url += FIREBASE_API_KEY;\n\n  String corpo = \"{\";\n  corpo += \"\\\"email\\\":\\\"\";\n  corpo += escaparJSON(String(FIREBASE_EMAIL));\n  corpo += \"\\\",\";\n  corpo += \"\\\"password\\\":\\\"\";\n  corpo += escaparJSON(String(FIREBASE_PASSWORD));\n  corpo += \"\\\",\";\n  corpo += \"\\\"returnSecureToken\\\":true\";\n  corpo += \"}\";\n\n  WiFiClientSecure cliente;\n  cliente.setInsecure();\n\n  HTTPClient http;\n\n  if (!http.begin(cliente, url)) {\n    Serial.println(\"Firebase Auth: falha no http.begin().\");\n    invalidarFirebaseAuth();\n    return false;\n  }\n\n  http.setConnectTimeout(12000);\n  http.setTimeout(20000);\n\n  http.addHeader(\n    \"Content-Type\",\n    \"application/json\"\n  );\n\n  Serial.println();\n  Serial.println(\"========================================\");\n  Serial.println(\"FIREBASE AUTH: realizando login...\");\n  Serial.print(\"Usuario: \");\n  Serial.println(FIREBASE_EMAIL);\n\n  int codigoHTTP = http.POST(corpo);\n\n  if (codigoHTTP <= 0) {\n    Serial.print(\"Firebase Auth erro HTTP \");\n    Serial.println(codigoHTTP);\n    Serial.print(\"Descricao: \");\n    Serial.println(http.errorToString(codigoHTTP));\n\n    http.end();\n    invalidarFirebaseAuth();\n    return false;\n  }\n\n  String resposta = http.getString();\n  http.end();\n\n  if (\n    codigoHTTP < 200 ||\n    codigoHTTP >= 300\n  ) {\n    Serial.print(\"Firebase Auth recusado. HTTP \");\n    Serial.println(codigoHTTP);\n\n    // Nao imprime senha/tokens. A resposta de erro nao contem token valido.\n    Serial.println(resposta);\n\n    invalidarFirebaseAuth();\n    return false;\n  }\n\n  String uid =\n    extrairStringJSONAuth(\n      resposta,\n      \"localId\"\n    );\n\n  String idToken =\n    extrairStringJSONAuth(\n      resposta,\n      \"idToken\"\n    );\n\n  String refreshToken =\n    extrairStringJSONAuth(\n      resposta,\n      \"refreshToken\"\n    );\n\n  String expiresIn =\n    extrairStringJSONAuth(\n      resposta,\n      \"expiresIn\"\n    );\n\n  if (\n    uid.length() == 0 ||\n    idToken.length() == 0 ||\n    refreshToken.length() == 0\n  ) {\n    Serial.println(\n      \"Firebase Auth: resposta recebida, mas campos obrigatorios faltaram.\"\n    );\n\n    invalidarFirebaseAuth();\n    return false;\n  }\n\n  if (\n    uid !=\n    String(FIREBASE_UID_ESPERADO)\n  ) {\n    Serial.println();\n    Serial.println(\"========================================\");\n    Serial.println(\"ERRO: UID FIREBASE NAO AUTORIZADO!\");\n    Serial.print(\"UID recebido: \");\n    Serial.println(uid);\n    Serial.print(\"UID esperado: \");\n    Serial.println(FIREBASE_UID_ESPERADO);\n    Serial.println(\"Sincronizacao bloqueada.\");\n    Serial.println(\"========================================\");\n\n    invalidarFirebaseAuth();\n    return false;\n  }\n\n  firebaseUIDAtual = uid;\n  firebaseIdToken = idToken;\n  firebaseRefreshToken = refreshToken;\n  firebaseAuthOK = true;\n\n  configurarValidadeToken(expiresIn);\n\n  Serial.println();\n  Serial.println(\"========================================\");\n  Serial.println(\"=== FIREBASE AUTH OK ===================\");\n  Serial.println(\"USUARIO AUTORIZADO.\");\n  Serial.print(\"UID: \");\n  Serial.println(firebaseUIDAtual);\n  Serial.println(\"ID token recebido: SIM\");\n  Serial.println(\"Refresh token recebido: SIM\");\n  Serial.print(\"Renovacao automatica antes de ~\");\n  Serial.print(\n    firebaseTokenValidadeUtilMs /\n    60000UL\n  );\n  Serial.println(\" min.\");\n  Serial.println(\"========================================\");\n\n  return true;\n}\n\nbool renovarFirebaseToken() {\n  if (\n    firebaseRefreshToken.length() == 0\n  ) {\n    return loginFirebaseAuth();\n  }\n\n  if (WiFi.status() != WL_CONNECTED) {\n    return false;\n  }\n\n  String url =\n    \"https://securetoken.googleapis.com/\"\n    \"v1/token?key=\";\n\n  url += FIREBASE_API_KEY;\n\n  String corpo =\n    \"grant_type=refresh_token&refresh_token=\";\n\n  corpo +=\n    urlEncodeAuth(\n      firebaseRefreshToken\n    );\n\n  WiFiClientSecure cliente;\n  cliente.setInsecure();\n\n  HTTPClient http;\n\n  if (!http.begin(cliente, url)) {\n    Serial.println(\n      \"Firebase Auth: falha ao iniciar renovacao.\"\n    );\n\n    return false;\n  }\n\n  http.setConnectTimeout(12000);\n  http.setTimeout(20000);\n\n  http.addHeader(\n    \"Content-Type\",\n    \"application/x-www-form-urlencoded\"\n  );\n\n  Serial.println();\n  Serial.println(\n    \"Firebase Auth: renovando ID token...\"\n  );\n\n  int codigoHTTP =\n    http.POST(corpo);\n\n  if (codigoHTTP <= 0) {\n    Serial.print(\n      \"Falha ao renovar token. HTTP \"\n    );\n    Serial.println(codigoHTTP);\n    Serial.print(\"Descricao: \");\n    Serial.println(\n      http.errorToString(codigoHTTP)\n    );\n\n    http.end();\n    return false;\n  }\n\n  String resposta =\n    http.getString();\n\n  http.end();\n\n  if (\n    codigoHTTP < 200 ||\n    codigoHTTP >= 300\n  ) {\n    Serial.print(\n      \"Firebase recusou renovacao. HTTP \"\n    );\n    Serial.println(codigoHTTP);\n\n    // Se refresh token deixou de ser valido,\n    // o proximo passo sera novo login.\n    invalidarFirebaseAuth();\n    return false;\n  }\n\n  String novoIdToken =\n    extrairStringJSONAuth(\n      resposta,\n      \"id_token\"\n    );\n\n  String novoRefreshToken =\n    extrairStringJSONAuth(\n      resposta,\n      \"refresh_token\"\n    );\n\n  String expiresIn =\n    extrairStringJSONAuth(\n      resposta,\n      \"expires_in\"\n    );\n\n  String uid =\n    extrairStringJSONAuth(\n      resposta,\n      \"user_id\"\n    );\n\n  if (\n    uid.length() == 0 ||\n    novoIdToken.length() == 0 ||\n    novoRefreshToken.length() == 0\n  ) {\n    Serial.println(\n      \"Firebase Auth: resposta de renovacao incompleta.\"\n    );\n\n    invalidarFirebaseAuth();\n    return false;\n  }\n\n  if (\n    uid !=\n    String(FIREBASE_UID_ESPERADO)\n  ) {\n    Serial.println(\n      \"Firebase Auth: UID inesperado na renovacao.\"\n    );\n\n    invalidarFirebaseAuth();\n    return false;\n  }\n\n  firebaseUIDAtual = uid;\n  firebaseIdToken = novoIdToken;\n  firebaseRefreshToken = novoRefreshToken;\n  firebaseAuthOK = true;\n\n  configurarValidadeToken(expiresIn);\n\n  Serial.println();\n  Serial.println(\"========================================\");\n  Serial.println(\"=== TOKEN FIREBASE RENOVADO ============\");\n  Serial.println(\"Sincronizacao autenticada continua ativa.\");\n  Serial.println(\"========================================\");\n\n  return true;\n}\n\nbool garantirFirebaseAuth() {\n  if (!firebaseAuthOK) {\n    return loginFirebaseAuth();\n  }\n\n  if (firebaseTokenPrecisaRenovar()) {\n    if (renovarFirebaseToken()) {\n      return true;\n    }\n\n    // Caso a renovacao falhe por token invalido,\n    // tenta login completo novamente.\n    return loginFirebaseAuth();\n  }\n\n  return true;\n}\n\nbool httpFirebase(\n  const String& metodo,\n  const String& caminho,\n  const String& json\n) {\n  if (WiFi.status() != WL_CONNECTED || modoAPAtivo) {\n    return false;\n  }\n\n  WiFiClientSecure cliente;\n\n  // TEMPORARIO nesta fase de integracao.\n  // Depois vamos usar autenticacao e endurecer TLS/regras.\n  cliente.setInsecure();\n\n  HTTPClient http;\n\n  if (\n    !firebaseAuthOK ||\n    firebaseIdToken.length() == 0\n  ) {\n    Serial.println(\n      \"Firebase: requisicao bloqueada sem autenticacao.\"\n    );\n    return false;\n  }\n\n  String url =\n    String(FIREBASE_BASE) +\n    caminho +\n    \".json?auth=\" +\n    urlEncodeAuth(firebaseIdToken) +\n    \"&print=silent\";\n\n  if (!http.begin(cliente, url)) {\n    Serial.println(\"Firebase: falha no http.begin()\");\n    return false;\n  }\n\n  // Timeout de conexao e leitura mais tolerantes a hotspot/rede instavel.\n  http.setConnectTimeout(12000);\n  http.setTimeout(20000);\n  http.addHeader(\"Content-Type\", \"application/json\");\n\n  int codigo = -1;\n\n  if (metodo == \"PUT\") {\n    codigo = http.PUT(json);\n  }\n  else if (metodo == \"PATCH\") {\n    codigo = http.sendRequest(\"PATCH\", json);\n  }\n  else {\n    http.end();\n    return false;\n  }\n\n  bool ok = (codigo >= 200 && codigo < 300);\n\n  if (!ok) {\n    Serial.print(\"Firebase erro HTTP \");\n    Serial.print(codigo);\n    Serial.print(\" em \");\n    Serial.println(caminho);\n\n    if (codigo < 0) {\n      Serial.print(\"Descricao: \");\n      Serial.println(http.errorToString(codigo));\n    }\n\n    if (codigo > 0) {\n      String resposta = http.getString();\n\n      if (resposta.length() > 0) {\n        Serial.print(\"Resposta: \");\n        Serial.println(resposta);\n      }\n    }\n\n    // 401/403 podem indicar token expirado/revogado ou regra negando acesso.\n    if (\n      codigo == 401 ||\n      codigo == 403\n    ) {\n      Serial.println(\n        \"Firebase: autenticacao sera refeita antes da proxima tentativa.\"\n      );\n\n      invalidarFirebaseAuth();\n    }\n\n    // Retry controlado: nao bombardeia o Firebase/rede.\n    proximaTentativaFirebase =\n      millis() + INTERVALO_RETRY_FIREBASE;\n\n    Serial.print(\"Nova tentativa Firebase em aproximadamente \");\n    Serial.print(INTERVALO_RETRY_FIREBASE / 1000);\n    Serial.println(\" segundos.\");\n  }\n  else {\n    proximaTentativaFirebase =\n      millis() + INTERVALO_SYNC;\n\n    if (!firebaseConfirmadoNestaConexao) {\n      firebaseConfirmadoNestaConexao = true;\n\n      Serial.println();\n      Serial.println(\"========================================\");\n      Serial.println(\"=== INTERNET + FIREBASE CONFIRMADOS! ===\");\n      Serial.println(\"Sincronizacao online disponivel.\");\n      Serial.println(\"========================================\");\n    }\n  }\n\n  http.end();\n  return ok;\n}\n\n\n// =====================================================\n// CONTROLE GLOBAL - FIREBASE REST\n// =====================================================\n\nbool httpFirebaseGET(\n  const String& caminho,\n  String& resposta\n) {\n  resposta = \"\";\n\n  if (WiFi.status() != WL_CONNECTED || modoAPAtivo) {\n    return false;\n  }\n\n  if (\n    !firebaseAuthOK ||\n    firebaseIdToken.length() == 0\n  ) {\n    return false;\n  }\n\n  WiFiClientSecure cliente;\n  cliente.setInsecure();\n\n  HTTPClient http;\n\n  String url =\n    String(FIREBASE_BASE) +\n    caminho +\n    \".json?auth=\" +\n    urlEncodeAuth(firebaseIdToken);\n\n  if (!http.begin(cliente, url)) {\n    return false;\n  }\n\n  http.setConnectTimeout(12000);\n  http.setTimeout(20000);\n\n  int codigo = http.GET();\n\n  bool ok =\n    codigo >= 200 &&\n    codigo < 300;\n\n  if (ok) {\n    resposta = http.getString();\n  }\n  else {\n    Serial.print(\"Firebase GET erro HTTP \");\n    Serial.print(codigo);\n    Serial.print(\" em \");\n    Serial.println(caminho);\n\n    if (\n      codigo == 401 ||\n      codigo == 403\n    ) {\n      invalidarFirebaseAuth();\n    }\n\n    proximaTentativaFirebase =\n      millis() + INTERVALO_RETRY_FIREBASE;\n  }\n\n  http.end();\n  return ok;\n}\n\nbool extrairStringJSONSimples(\n  const String& json,\n  const String& chave,\n  String& valor\n) {\n  String busca =\n    \"\\\"\" + chave + \"\\\":\\\"\";\n\n  int inicio = json.indexOf(busca);\n\n  if (inicio < 0) return false;\n\n  inicio += busca.length();\n\n  int fim = json.indexOf('\"', inicio);\n\n  if (fim < 0) return false;\n\n  valor = json.substring(inicio, fim);\n  return true;\n}\n\nbool extrairBoolJSONSimples(\n  const String& json,\n  const String& chave,\n  bool& valor\n) {\n  String busca =\n    \"\\\"\" + chave + \"\\\":\";\n\n  int inicio = json.indexOf(busca);\n\n  if (inicio < 0) return false;\n\n  inicio += busca.length();\n\n  while (\n    inicio < json.length() &&\n    (\n      json[inicio] == ' ' ||\n      json[inicio] == '\\n' ||\n      json[inicio] == '\\r' ||\n      json[inicio] == '\\t'\n    )\n  ) {\n    inicio++;\n  }\n\n  if (json.substring(inicio).startsWith(\"true\")) {\n    valor = true;\n    return true;\n  }\n\n  if (json.substring(inicio).startsWith(\"false\")) {\n    valor = false;\n    return true;\n  }\n\n  return false;\n}\n\nvoid aplicarEstadoAberturaGlobal(\n  bool aberta\n) {\n  if (mutexDados) {\n    xSemaphoreTake(mutexDados, portMAX_DELAY);\n  }\n\n  if (votacaoAberta != aberta) {\n    votacaoAberta = aberta;\n    geracaoDados++;\n    salvarDirty(true);\n    salvarEstadoGeral();\n\n    atualizarInterfacePorControleGlobal = true;\n  }\n\n  if (mutexDados) {\n    xSemaphoreGive(mutexDados);\n  }\n}\n\nvoid aplicarNovaRodadaGlobal(\n  const String& novaRodada,\n  bool aberta\n) {\n  if (novaRodada.length() == 0) return;\n\n  if (mutexDados) {\n    xSemaphoreTake(mutexDados, portMAX_DELAY);\n  }\n\n  unsigned long sequenciaPreservada =\n    sequenciaGlobal;\n\n  unsigned long comandosPreservados =\n    contadorComandosGlobais;\n\n  // Limpa somente a namespace local da urna.\n  // Credenciais Wi-Fi ficam em outra namespace.\n  memoria.begin(\"urna\", false);\n  memoria.clear();\n  memoria.end();\n\n  for (int i = 0; i < TOTAL_ELETRICA; i++) {\n    eletrica[i].votos = 0;\n    eletrica[i].ordemAtingida = 0;\n  }\n\n  for (int i = 0; i < TOTAL_RENOVAVEIS; i++) {\n    renovaveis[i].votos = 0;\n    renovaveis[i].ordemAtingida = 0;\n  }\n\n  sequenciaGlobal = sequenciaPreservada;\n  contadorComandosGlobais = comandosPreservados;\n\n  rodadaLocal = novaRodada;\n  votacaoAberta = aberta;\n\n  geracaoDados++;\n\n  salvarDirty(true);\n  salvarEstadoGeral();\n\n  if (mutexDados) {\n    xSemaphoreGive(mutexDados);\n  }\n\n  // Qualquer voto pendente pertence a rodada anterior.\n  // Ele NAO pode reaparecer depois do reset global.\n  limparFilaPendentes();\n\n  atualizarInterfacePorControleGlobal = true;\n\n  Serial.println();\n  Serial.println(\"========================================\");\n  Serial.println(\"NOVA RODADA GLOBAL APLICADA\");\n  Serial.print(\"Rodada: \");\n  Serial.println(rodadaLocal);\n  Serial.println(\"Contadores locais zerados.\");\n  Serial.println(\"Fila antiga descartada.\");\n  Serial.println(\"========================================\");\n}\n\nbool publicarControleGlobal(\n  const String& rodada,\n  bool aberta\n) {\n  String json;\n  json.reserve(300);\n\n  json += \"{\";\n  json += \"\\\"rodada_id\\\":\\\"\";\n  json += escaparJSON(rodada);\n  json += \"\\\",\";\n  json += \"\\\"votacao_aberta\\\":\";\n  json += aberta ? \"true\" : \"false\";\n  json += \",\";\n  json += \"\\\"origem\\\":\\\"\";\n  json += String(ID_URNA);\n  json += \"\\\",\";\n  json += \"\\\"ultima_alteracao\\\":\";\n  json += \"{\\\".sv\\\":\\\"timestamp\\\"}\";\n  json += \"}\";\n\n  return httpFirebase(\n    \"PUT\",\n    \"/controle\",\n    json\n  );\n}\n\nbool sincronizarControleGlobal() {\n  String resposta;\n\n  if (!httpFirebaseGET(\n    \"/controle\",\n    resposta\n  )) {\n    controleGlobalConhecido = false;\n    return false;\n  }\n\n  resposta.trim();\n\n  // Primeira execucao da V19:\n  // cria o controle usando o estado local atual.\n  if (\n    resposta == \"null\" ||\n    resposta.length() == 0\n  ) {\n    if (!publicarControleGlobal(\n      rodadaLocal,\n      votacaoAberta\n    )) {\n      controleGlobalConhecido = false;\n      return false;\n    }\n\n    controleGlobalConhecido = true;\n    ultimaConsultaControleGlobal = millis();\n\n    Serial.println(\n      \"Controle global inicial criado no Firebase.\"\n    );\n\n    return true;\n  }\n\n  String rodadaRemota;\n  bool abertaRemota = true;\n\n  bool temRodada =\n    extrairStringJSONSimples(\n      resposta,\n      \"rodada_id\",\n      rodadaRemota\n    );\n\n  bool temAberta =\n    extrairBoolJSONSimples(\n      resposta,\n      \"votacao_aberta\",\n      abertaRemota\n    );\n\n  if (!temRodada || !temAberta) {\n    Serial.println(\n      \"Controle global invalido/incompleto.\"\n    );\n\n    controleGlobalConhecido = false;\n    return false;\n  }\n\n  if (rodadaRemota != rodadaLocal) {\n    aplicarNovaRodadaGlobal(\n      rodadaRemota,\n      abertaRemota\n    );\n  }\n  else {\n    aplicarEstadoAberturaGlobal(\n      abertaRemota\n    );\n  }\n\n  controleGlobalConhecido = true;\n  ultimaConsultaControleGlobal = millis();\n\n  return true;\n}\n\nvoid executarComandoGlobalPendente() {\n  int comando = comandoGlobalPendente;\n\n  if (comando == CMD_GLOBAL_NENHUM) {\n    return;\n  }\n\n  bool ok = false;\n\n  if (comando == CMD_GLOBAL_ZERAR) {\n    // Incrementa antes do envio e persiste.\n    // Assim um retry futuro nunca reutiliza o mesmo ID de rodada.\n    if (mutexDados) {\n      xSemaphoreTake(mutexDados, portMAX_DELAY);\n    }\n\n    contadorComandosGlobais++;\n    salvarEstadoGeral();\n\n    if (mutexDados) {\n      xSemaphoreGive(mutexDados);\n    }\n\n    String novaRodada =\n      String(\"R_\") +\n      ID_URNA +\n      \"_\" +\n      String(contadorComandosGlobais);\n\n    ok = publicarControleGlobal(\n      novaRodada,\n      true\n    );\n\n    if (ok) {\n      aplicarNovaRodadaGlobal(\n        novaRodada,\n        true\n      );\n    }\n  }\n  else if (\n    comando == CMD_GLOBAL_ENCERRAR ||\n    comando == CMD_GLOBAL_REABRIR\n  ) {\n    // Sempre rele a rodada oficial imediatamente antes de\n    // encerrar/reabrir. Isso impede uma urna com estado antigo\n    // de sobrescrever uma rodada nova criada pela outra urna.\n    if (sincronizarControleGlobal()) {\n      bool abrir =\n        comando == CMD_GLOBAL_REABRIR;\n\n      ok = publicarControleGlobal(\n        rodadaLocal,\n        abrir\n      );\n\n      if (ok) {\n        aplicarEstadoAberturaGlobal(\n          abrir\n        );\n      }\n    }\n  }\n\n  if (ok) {\n    resultadoComandoGlobal = 1;\n    controleGlobalConhecido = true;\n    ultimaConsultaControleGlobal = millis();\n  }\n  else {\n    resultadoComandoGlobal = -1;\n  }\n\n  comandoGlobalPendente =\n    CMD_GLOBAL_NENHUM;\n}\n\nbool enviarEventoPendente(const VotoPendente& voto) {\n  String codigo = String(voto.numero);\n  codigo += (voto.curso == 1) ? \"A\" : \"B\";\n\n  Projeto* projeto = buscarProjeto(voto.curso, voto.numero);\n\n  String nome = projeto ? String(projeto->nome) : String(\"\");\n\n  String json;\n  json.reserve(350);\n\n  json += \"{\";\n  json += \"\\\"urna\\\":\\\"\" + String(ID_URNA) + \"\\\",\";\n  json += \"\\\"rodada\\\":\\\"\" + escaparJSON(rodadaLocal) + \"\\\",\";\n  json += \"\\\"id\\\":\\\"\" + escaparJSON(voto.id) + \"\\\",\";\n  json += \"\\\"curso\\\":\\\"\";\n  json += (voto.curso == 1) ? \"eletrica\" : \"renovaveis\";\n  json += \"\\\",\";\n  json += \"\\\"codigo\\\":\\\"\" + codigo + \"\\\",\";\n  json += \"\\\"numero\\\":\" + String(voto.numero) + \",\";\n  json += \"\\\"nome\\\":\\\"\" + escaparJSON(nome) + \"\\\",\";\n  json += \"\\\"sequencia\\\":\" + String(voto.sequencia) + \",\";\n  json += \"\\\"votos_apos\\\":\" + String(voto.votosDepois) + \",\";\n  json += \"\\\"ordem_atingida\\\":\" + String(voto.ordemAtingida) + \",\";\n  json += \"\\\"timestamp_servidor\\\":{\\\".sv\\\":\\\"timestamp\\\"}\";\n  json += \"}\";\n\n  // PUT em uma chave fixa e unica:\n  // repetir a mesma requisicao nao cria voto duplicado.\n  String caminho =\n    String(\"/eventos/\") + ID_URNA + \"/\" + voto.id;\n\n  return httpFirebase(\"PUT\", caminho, json);\n}\n\nbool vemAntesSync(Projeto* a, Projeto* b) {\n  if (a->votos != b->votos) {\n    return a->votos > b->votos;\n  }\n\n  if (a->ordemAtingida != b->ordemAtingida) {\n    if (a->ordemAtingida == 0) return false;\n    if (b->ordemAtingida == 0) return true;\n\n    return a->ordemAtingida < b->ordemAtingida;\n  }\n\n  return a->numero < b->numero;\n}\n\nString jsonRankingCurso(byte curso) {\n  Projeto* lista[50];\n  int quantidade = 0;\n\n  if (curso == 1) {\n    quantidade = TOTAL_ELETRICA;\n\n    for (int i = 0; i < quantidade; i++) {\n      lista[i] = &eletrica[i];\n    }\n  }\n  else {\n    quantidade = TOTAL_RENOVAVEIS;\n\n    for (int i = 0; i < quantidade; i++) {\n      lista[i] = &renovaveis[i];\n    }\n  }\n\n  for (int i = 0; i < quantidade - 1; i++) {\n    for (int j = i + 1; j < quantidade; j++) {\n      if (vemAntesSync(lista[j], lista[i])) {\n        Projeto* temp = lista[i];\n        lista[i] = lista[j];\n        lista[j] = temp;\n      }\n    }\n  }\n\n  String json = \"{\";\n  bool primeiro = true;\n  int posicao = 1;\n\n  for (int i = 0; i < quantidade && posicao <= 3; i++) {\n    if (lista[i]->votos == 0) continue;\n\n    if (!primeiro) json += \",\";\n    primeiro = false;\n\n    String codigo = String(lista[i]->numero);\n    codigo += (curso == 1) ? \"A\" : \"B\";\n\n    json += \"\\\"\" + String(posicao) + \"\\\":{\";\n    json += \"\\\"codigo\\\":\\\"\" + codigo + \"\\\",\";\n    json += \"\\\"nome\\\":\\\"\" + escaparJSON(String(lista[i]->nome)) + \"\\\"\";\n    json += \"}\";\n\n    posicao++;\n  }\n\n  json += \"}\";\n  return json;\n}\n\nString jsonProjetosCurso(byte curso) {\n  String json = \"{\";\n  bool primeiro = true;\n\n  if (curso == 1) {\n    for (int i = 0; i < TOTAL_ELETRICA; i++) {\n      if (!primeiro) json += \",\";\n      primeiro = false;\n\n      String codigo = String(eletrica[i].numero) + \"A\";\n\n      json += \"\\\"\" + codigo + \"\\\":{\";\n      json += \"\\\"nome\\\":\\\"\" + escaparJSON(String(eletrica[i].nome)) + \"\\\",\";\n      json += \"\\\"rodada\\\":\\\"\" + escaparJSON(rodadaLocal) + \"\\\",\";\n      json += \"\\\"votos\\\":\" + String(eletrica[i].votos) + \",\";\n      json += \"\\\"ordem\\\":\" + String(eletrica[i].ordemAtingida);\n      json += \"}\";\n    }\n  }\n  else {\n    for (int i = 0; i < TOTAL_RENOVAVEIS; i++) {\n      if (!primeiro) json += \",\";\n      primeiro = false;\n\n      String codigo = String(renovaveis[i].numero) + \"B\";\n\n      json += \"\\\"\" + codigo + \"\\\":{\";\n      json += \"\\\"nome\\\":\\\"\" + escaparJSON(String(renovaveis[i].nome)) + \"\\\",\";\n      json += \"\\\"rodada\\\":\\\"\" + escaparJSON(rodadaLocal) + \"\\\",\";\n      json += \"\\\"votos\\\":\" + String(renovaveis[i].votos) + \",\";\n      json += \"\\\"ordem\\\":\" + String(renovaveis[i].ordemAtingida);\n      json += \"}\";\n    }\n  }\n\n  json += \"}\";\n  return json;\n}\n\nbool enviarSnapshotCompleto() {\n  if (WiFi.status() != WL_CONNECTED || modoAPAtivo) {\n    return false;\n  }\n\n  unsigned long geracaoCapturada = 0;\n  String json;\n  json.reserve(14000);\n\n  if (mutexDados) {\n    xSemaphoreTake(mutexDados, portMAX_DELAY);\n  }\n\n  geracaoCapturada = geracaoDados;\n\n  json += \"{\";\n\n  // Status\n  json += \"\\\"status\\\":{\";\n  json += \"\\\"online\\\":true,\";\n  json += \"\\\"urna\\\":\\\"\" + String(ID_URNA) + \"\\\",\";\n  json += \"\\\"rodada\\\":\\\"\" + escaparJSON(rodadaLocal) + \"\\\",\";\n  json += \"\\\"wifi\\\":\\\"\" + escaparJSON(WiFi.SSID()) + \"\\\",\";\n  json += \"\\\"ip\\\":\\\"\" + WiFi.localIP().toString() + \"\\\",\";\n  json += \"\\\"pendentes\\\":\" + String(contarPendentes()) + \",\";\n  json += \"\\\"sequencia\\\":\" + String(sequenciaGlobal) + \",\";\n  json += \"\\\"votacao_aberta\\\":\";\n  json += votacaoAberta ? \"true\" : \"false\";\n  json += \",\";\n  json += \"\\\"ultima_sincronizacao\\\":{\\\".sv\\\":\\\"timestamp\\\"}\";\n  json += \"},\";\n\n  // Projetos internos\n  json += \"\\\"projetos\\\":{\";\n  json += \"\\\"eletrica\\\":\" + jsonProjetosCurso(1) + \",\";\n  json += \"\\\"renovaveis\\\":\" + jsonProjetosCurso(2);\n  json += \"},\";\n\n  // Ranking local desta urna: permanece privado.\n  json += \"\\\"ranking_local\\\":{\";\n  json += \"\\\"eletrica\\\":\" + jsonRankingCurso(1) + \",\";\n  json += \"\\\"renovaveis\\\":\" + jsonRankingCurso(2);\n  json += \"}\";\n\n  json += \"}\";\n\n  if (mutexDados) {\n    xSemaphoreGive(mutexDados);\n  }\n\n  Serial.print(\"Firebase: enviando snapshot (\");\n  Serial.print(json.length());\n  Serial.println(\" bytes)...\");\n\n  String caminhoDispositivo =\n    String(\"/dispositivos/\") + ID_URNA;\n\n  bool ok = httpFirebase(\n    \"PATCH\",\n    caminhoDispositivo,\n    json\n  );\n\n  if (ok) {\n    if (mutexDados) {\n      xSemaphoreTake(mutexDados, portMAX_DELAY);\n    }\n\n    // So limpa a flag se NADA mudou enquanto o HTTPS estava rodando.\n    if (geracaoDados == geracaoCapturada) {\n      salvarDirty(false);\n      Serial.println(\"Firebase: snapshot sincronizado.\");\n    }\n    else {\n      salvarDirty(true);\n      Serial.println(\n        \"Firebase: snapshot enviado, mas houve novo voto durante o envio.\"\n      );\n      Serial.println(\n        \"Um novo snapshot sera enviado depois.\"\n      );\n    }\n\n    if (mutexDados) {\n      xSemaphoreGive(mutexDados);\n    }\n  }\n\n  return ok;\n}\n\nbool wifiEstavelParaFirebase() {\n  if (modoAPAtivo) return false;\n  if (estadoWiFi != WIFI_CONECTADO) return false;\n  if (WiFi.status() != WL_CONNECTED) return false;\n  if (wifiConectadoDesde == 0) return false;\n\n  return (\n    millis() - wifiConectadoDesde >=\n    TEMPO_ESTABILIZACAO_WIFI\n  );\n}\n\nvoid sincronizarFirebaseSePossivel() {\n  if (interfaceAtualizando) return;\n\n  if (\n    liberarSyncApos != 0 &&\n    (long)(millis() - liberarSyncApos) < 0\n  ) {\n    return;\n  }\n\n  if (!wifiEstavelParaFirebase()) return;\n\n  if (millis() < proximaTentativaFirebase) return;\n\n  // Login/refresh sempre na tarefa de background.\n  if (!garantirFirebaseAuth()) {\n    proximaTentativaFirebase =\n      millis() + INTERVALO_RETRY_FIREBASE;\n\n    return;\n  }\n\n  // Comandos administrativos globais tem prioridade e podem\n  // ser executados mesmo com a interface no menu do operador.\n  if (\n    comandoGlobalPendente !=\n    CMD_GLOBAL_NENHUM\n  ) {\n    executarComandoGlobalPendente();\n    return;\n  }\n\n  // REGRA CRITICA:\n  // ao conectar/reconectar, a urna obrigatoriamente consulta\n  // o controle global ANTES de enviar snapshot ou voto pendente.\n  bool horaDeConsultarControle =\n    !controleGlobalConhecido ||\n    (\n      millis() - ultimaConsultaControleGlobal >=\n      INTERVALO_CONTROLE_GLOBAL\n    );\n\n  if (horaDeConsultarControle) {\n    if (!sincronizarControleGlobal()) {\n      return;\n    }\n  }\n\n  if (!controleGlobalConhecido) return;\n\n  // Votos/snapshots normais so saem quando a urna esta ociosa.\n  if (estado != TELA_INICIAL) return;\n\n  if (\n    millis() - ultimaTentativaSync <\n    INTERVALO_SYNC\n  ) {\n    return;\n  }\n\n  ultimaTentativaSync = millis();\n\n  if (dadosSujos) {\n    enviarSnapshotCompleto();\n    return;\n  }\n\n  VotoPendente voto;\n\n  if (lerPrimeiroPendente(voto)) {\n    Serial.print(\"Firebase: sincronizando evento \");\n    Serial.println(voto.id);\n\n    if (enviarEventoPendente(voto)) {\n      if (removerPrimeiroPendente()) {\n        Serial.println(\n          \"Firebase: evento confirmado e removido da fila.\"\n        );\n      }\n    }\n\n    return;\n  }\n}\n\n// =====================================================\n// TAREFA FIREBASE EM BACKGROUND\n// =====================================================\n\nvoid tarefaSincronizacaoFirebase(void* parametro) {\n  Serial.println(\"Tarefa Firebase em background iniciada.\");\n\n  while (true) {\n    sincronizarFirebaseSePossivel();\n\n    // Pequeno descanso para o loop principal continuar muito responsivo.\n    vTaskDelay(pdMS_TO_TICKS(200));\n  }\n}\n\nvoid iniciarTarefaFirebase() {\n  if (tarefaFirebaseHandle != nullptr) {\n    return;\n  }\n\n  BaseType_t criada = xTaskCreate(\n    tarefaSincronizacaoFirebase,\n    \"firebase_sync\",\n    12288,\n    nullptr,\n    1,\n    &tarefaFirebaseHandle\n  );\n\n  if (criada == pdPASS) {\n    Serial.println(\n      \"Sincronizacao Firebase separada do teclado/LCD: OK\"\n    );\n  }\n  else {\n    tarefaFirebaseHandle = nullptr;\n\n    Serial.println(\n      \"ERRO: nao foi possivel criar tarefa Firebase.\"\n    );\n  }\n}\n\n// =====================================================\n// TELAS PRINCIPAIS\n// =====================================================\n\nvoid mostrarTelaInicial() {\n  // IMPORTANTE:\n  // Nao define TELA_INICIAL antes de terminar de desenhar o LCD.\n  // A tarefa Firebase so sincroniza em TELA_INICIAL; se liberarmos\n  // o estado cedo demais, ela pode iniciar HTTPS exatamente entre\n  // lcd.clear() e as escritas seguintes, deixando a tela aparentemente\n  // vazia por varios segundos em uma rede lenta.\n\n  interfaceAtualizando = true;\n\n  numeroDigitado = \"\";\n  projetoSelecionado = nullptr;\n\n  lcd.clear();\n\n  if (!votacaoAberta) {\n    escreverLinha(0, \"VOTACAO ENCERRADA\");\n    escreverLinha(1, \"\");\n    escreverLinha(2, \"Novos votos bloquead\");\n    escreverLinha(3, \"* Modo operador\");\n  }\n  else {\n    escreverLinha(0, \"ESCOLHA O CURSO\");\n    escreverLinha(1, \"\");\n    escreverLinha(2, \"1 - Eng. Eletrica\");\n    escreverLinha(3, \"2 - Eng. Renovaveis\");\n  }\n\n  // Só agora a tarefa de background pode considerar a urna ociosa.\n  estado = TELA_INICIAL;\n\n  // Dá uma pequena folga para a interface ficar estável antes de HTTPS.\n  liberarSyncApos =\n    millis() + TEMPO_PROTECAO_LCD_APOS_TELA;\n\n  interfaceAtualizando = false;\n}\n\nvoid mostrarTelaProjeto() {\n  estado = DIGITAR_PROJETO;\n  numeroDigitado = \"\";\n\n  lcd.clear();\n\n  if (cursoSelecionado == 1) {\n    escreverLinha(0, \"ENG. ELETRICA\");\n  } else {\n    escreverLinha(0, \"ENG. RENOVAVEIS\");\n  }\n\n  escreverLinha(1, \"\");\n  escreverLinha(2, \"Projeto: _\");\n  escreverLinha(3, \"# Confirma  * Apaga\");\n}\n\nvoid atualizarNumero() {\n  String texto = \"Projeto: \";\n  texto += numeroDigitado.length() == 0 ? \"_\" : numeroDigitado;\n  escreverLinha(2, texto);\n}\n\nProjeto* buscarProjeto(byte curso, int numero) {\n  if (curso == 1) {\n    for (int i = 0; i < TOTAL_ELETRICA; i++) {\n      if (eletrica[i].numero == numero) return &eletrica[i];\n    }\n  } else {\n    for (int i = 0; i < TOTAL_RENOVAVEIS; i++) {\n      if (renovaveis[i].numero == numero) return &renovaveis[i];\n    }\n  }\n\n  return nullptr;\n}\n\nvoid mostrarConfirmacao() {\n  estado = CONFIRMAR_VOTO;\n  lcd.clear();\n\n  String codigo = String(projetoSelecionado->numero);\n  codigo += cursoSelecionado == 1 ? \"A\" : \"B\";\n\n  escreverLinha(0, \"CONFIRMAR VOTO?\");\n  escreverLinha(1, codigo + \" - \" + String(projetoSelecionado->nome));\n  escreverLinha(2, limitarTexto(String(projetoSelecionado->nome), 20));\n  escreverLinha(3, \"# SIM       * NAO\");\n}\n\nvoid registrarVoto() {\n  if (!votacaoAberta || projetoSelecionado == nullptr) {\n    mostrarTelaInicial();\n    return;\n  }\n\n  byte cursoVoto = cursoSelecionado;\n  byte numeroVoto = projetoSelecionado->numero;\n\n  unsigned long sequenciaVoto = 0;\n  unsigned long votosDepois = 0;\n  unsigned long ordemDepois = 0;\n\n  String nomeProjeto = String(projetoSelecionado->nome);\n\n  // =================================================\n  // 1) PRIMEIRO: grava localmente.\n  // Essa parte e curta e protegida do snapshot de background.\n  // =================================================\n\n  if (mutexDados) {\n    xSemaphoreTake(mutexDados, portMAX_DELAY);\n  }\n\n  sequenciaGlobal++;\n\n  projetoSelecionado->votos++;\n  projetoSelecionado->ordemAtingida = sequenciaGlobal;\n\n  geracaoDados++;\n\n  sequenciaVoto = sequenciaGlobal;\n  votosDepois = projetoSelecionado->votos;\n  ordemDepois = projetoSelecionado->ordemAtingida;\n\n  salvarDirty(true);\n  salvarProjeto(cursoVoto, projetoSelecionado);\n\n  if (mutexDados) {\n    xSemaphoreGive(mutexDados);\n  }\n\n  // =================================================\n  // 2) Cria evento persistente para sincronizar.\n  // =================================================\n\n  String idVoto = criarIdVoto(sequenciaVoto);\n\n  adicionarPendente(\n    idVoto,\n    cursoVoto,\n    numeroVoto,\n    sequenciaVoto,\n    votosDepois,\n    ordemDepois\n  );\n\n  lcd.clear();\n\n  String codigo = String(numeroVoto);\n  codigo += cursoVoto == 1 ? \"A\" : \"B\";\n\n  escreverLinha(0, \"VOTO REGISTRADO!\");\n  escreverLinha(1, \"\");\n  escreverLinha(2, codigo + \" - \" + nomeProjeto);\n\n  if (WiFi.status() == WL_CONNECTED) {\n    escreverLinha(3, \"Salvo! Sync em fundo\");\n  } else {\n    escreverLinha(3, \"Salvo localmente!\");\n  }\n\n  Serial.println();\n  Serial.println(\"=== VOTO LOCAL SALVO ===\");\n  Serial.print(\"ID: \");\n  Serial.println(idVoto);\n  Serial.print(\"Codigo: \");\n  Serial.println(codigo);\n  Serial.print(\"Votos do projeto: \");\n  Serial.println(votosDepois);\n  Serial.print(\"Pendentes: \");\n  Serial.println(contarPendentes());\n\n  // Somente a confirmacao visual dura um instante.\n  // Firebase NAO roda aqui e nao bloqueia o teclado.\n  delay(1000);\n\n  mostrarTelaInicial();\n\n  Serial.println(\n    \"LCD: tela inicial restaurada apos o voto.\"\n  );\n}\n\n// =====================================================\n// MODO OPERADOR\n// =====================================================\n\nvoid mostrarSenhaOperador() {\n  estado = SENHA_OPERADOR;\n  senhaDigitada = \"\";\n\n  lcd.clear();\n  escreverLinha(0, \"MODO OPERADOR\");\n  escreverLinha(1, \"\");\n  escreverLinha(2, \"Senha: _\");\n  escreverLinha(3, \"# OK       * Sair\");\n}\n\nvoid mostrarMenuOperador() {\n  estado = MENU_OPERADOR;\n  lcd.clear();\n\n  if (paginaMenuOperador == 1) {\n    escreverLinha(0, \"MODO OPERADOR  1/3\");\n    escreverLinha(1, \"1 - Ranking Eletrica\");\n    escreverLinha(2, \"2 - Ranking Renovav.\");\n    escreverLinha(3, \"A - Proxima pagina\");\n  }\n  else if (paginaMenuOperador == 2) {\n    escreverLinha(0, \"MODO OPERADOR  2/3\");\n    escreverLinha(1, \"3 - Total de votos\");\n    escreverLinha(2, \"4 - Encerrar/Reabrir\");\n    escreverLinha(3, \"A Prox.  B Voltar\");\n  }\n  else {\n    escreverLinha(0, \"MODO OPERADOR  3/3\");\n    escreverLinha(1, \"5 - Zerar votacao\");\n    escreverLinha(2, \"6 - Status Wi-Fi\");\n    escreverLinha(3, \"B Voltar    * Sair\");\n  }\n}\n\n// =====================================================\n// RANKING\n// =====================================================\n\nbool vemAntes(Projeto* a, Projeto* b) {\n  if (a->votos != b->votos) {\n    return a->votos > b->votos;\n  }\n\n  if (a->ordemAtingida != b->ordemAtingida) {\n    if (a->ordemAtingida == 0) return false;\n    if (b->ordemAtingida == 0) return true;\n    return a->ordemAtingida < b->ordemAtingida;\n  }\n\n  return a->numero < b->numero;\n}\n\nvoid montarRanking(byte curso) {\n  cursoRanking = curso;\n  indiceRanking = 0;\n\n  if (curso == 1) {\n    quantidadeRanking = TOTAL_ELETRICA;\n    for (int i = 0; i < quantidadeRanking; i++) {\n      rankingAtual[i] = &eletrica[i];\n    }\n  } else {\n    quantidadeRanking = TOTAL_RENOVAVEIS;\n    for (int i = 0; i < quantidadeRanking; i++) {\n      rankingAtual[i] = &renovaveis[i];\n    }\n  }\n\n  for (int i = 0; i < quantidadeRanking - 1; i++) {\n    for (int j = i + 1; j < quantidadeRanking; j++) {\n      if (vemAntes(rankingAtual[j], rankingAtual[i])) {\n        Projeto* temp = rankingAtual[i];\n        rankingAtual[i] = rankingAtual[j];\n        rankingAtual[j] = temp;\n      }\n    }\n  }\n\n  int validos = 0;\n  for (int i = 0; i < quantidadeRanking && validos < 3; i++) {\n    if (rankingAtual[i]->votos > 0) validos++;\n  }\n\n  quantidadeRanking = validos;\n}\n\nvoid mostrarResultadoAtual() {\n  lcd.clear();\n\n  if (quantidadeRanking == 0) {\n    escreverLinha(0, cursoRanking == 1 ? \"RANKING ELETRICA\" : \"RANKING RENOVAVEIS\");\n    escreverLinha(1, \"\");\n    escreverLinha(2, \"Sem votos ainda\");\n    escreverLinha(3, \"* Voltar\");\n    return;\n  }\n\n  Projeto* p = rankingAtual[indiceRanking];\n\n  String codigo = String(p->numero);\n  codigo += cursoRanking == 1 ? \"A\" : \"B\";\n\n  escreverLinha(\n    0,\n    cursoRanking == 1 ? \"RANKING ELETRICA\" : \"RANKING RENOVAVEIS\"\n  );\n\n  escreverLinha(\n    1,\n    String(indiceRanking + 1) + \"o - \" + codigo\n  );\n\n  escreverLinha(\n    2,\n    String(p->nome)\n  );\n\n  escreverLinha(\n    3,\n    String(p->votos) + \" votos  A> B< *Vol\"\n  );\n}\n\nvoid abrirTop3(byte curso) {\n  montarRanking(curso);\n  estado = RESULTADO_NAVEGAVEL;\n  mostrarResultadoAtual();\n}\n\n// =====================================================\n// TOTAIS\n// =====================================================\n\nunsigned long totalCurso(byte curso) {\n  unsigned long total = 0;\n\n  if (curso == 1) {\n    for (int i = 0; i < TOTAL_ELETRICA; i++) {\n      total += eletrica[i].votos;\n    }\n  } else {\n    for (int i = 0; i < TOTAL_RENOVAVEIS; i++) {\n      total += renovaveis[i].votos;\n    }\n  }\n\n  return total;\n}\n\nvoid mostrarTotais() {\n  unsigned long totalA = totalCurso(1);\n  unsigned long totalB = totalCurso(2);\n\n  lcd.clear();\n  escreverLinha(0, \"TOTAL DE VOTOS\");\n  escreverLinha(1, \"Eletrica: \" + String(totalA));\n  escreverLinha(2, \"Renovaveis: \" + String(totalB));\n  escreverLinha(3, \"Geral: \" + String(totalA + totalB));\n\n  delay(3500);\n  mostrarMenuOperador();\n}\n\n// =====================================================\n// ENCERRAR / REABRIR\n// =====================================================\n\nvoid pedirEncerrarOuReabrir() {\n  lcd.clear();\n\n  if (votacaoAberta) {\n    estado = CONFIRMAR_ENCERRAR;\n    escreverLinha(0, \"ENCERRAR VOTACAO?\");\n    escreverLinha(1, \"\");\n    escreverLinha(2, \"# Confirma\");\n    escreverLinha(3, \"* Cancela\");\n  } else {\n    estado = CONFIRMAR_REABRIR;\n    escreverLinha(0, \"REABRIR VOTACAO?\");\n    escreverLinha(1, \"\");\n    escreverLinha(2, \"# Confirma\");\n    escreverLinha(3, \"* Cancela\");\n  }\n}\n\n// =====================================================\n// ZERAR\n// =====================================================\n\nvoid pedirSenhaZerar() {\n  estado = SENHA_ZERAR;\n  senhaDigitada = \"\";\n\n  lcd.clear();\n  escreverLinha(0, \"ZERAR VOTACAO\");\n  escreverLinha(1, \"Confirme sua senha\");\n  escreverLinha(2, \"Senha: _\");\n  escreverLinha(3, \"# OK     * Cancela\");\n}\n\nvoid pedirZerar() {\n  estado = CONFIRMAR_ZERAR;\n\n  lcd.clear();\n  escreverLinha(0, \"ZERAR TUDO?\");\n  escreverLinha(1, \"Esta acao e definitiva\");\n  escreverLinha(2, \"# CONFIRMAR\");\n  escreverLinha(3, \"* CANCELAR\");\n}\n\nvoid iniciarSolicitacaoComandoGlobal(\n  int tipo,\n  const String& titulo\n) {\n  // Para manter as duas urnas e o site coerentes,\n  // comandos administrativos globais nao sao executados offline.\n  if (\n    WiFi.status() != WL_CONNECTED ||\n    modoAPAtivo\n  ) {\n    lcd.clear();\n    escreverLinha(0, \"SEM INTERNET\");\n    escreverLinha(1, \"Acao nao executada\");\n    escreverLinha(2, \"Reconecte o Wi-Fi\");\n    escreverLinha(3, \"e tente novamente\");\n\n    delay(2200);\n    mostrarMenuOperador();\n    return;\n  }\n\n  if (\n    aguardandoComandoGlobalUI ||\n    comandoGlobalPendente !=\n      CMD_GLOBAL_NENHUM\n  ) {\n    return;\n  }\n\n  comandoGlobalUIAtual = tipo;\n  resultadoComandoGlobal = 0;\n  aguardandoComandoGlobalUI = true;\n  comandoGlobalPendente = tipo;\n\n  lcd.clear();\n  escreverLinha(0, titulo);\n  escreverLinha(1, \"\");\n  escreverLinha(2, \"Sincronizando...\");\n  escreverLinha(3, \"Aguarde\");\n}\n\nvoid executarZerar() {\n  iniciarSolicitacaoComandoGlobal(\n    CMD_GLOBAL_ZERAR,\n    \"ZERANDO SISTEMA\"\n  );\n}\n\n// =====================================================\n// STATUS WIFI\n// =====================================================\n\nvoid mostrarStatusWiFi() {\n  estado = STATUS_WIFI;\n  lcd.clear();\n\n  if (paginaStatusWiFi == 1) {\n    escreverLinha(0, \"STATUS DO WIFI  1/2\");\n\n    if (modoAPAtivo) {\n      escreverLinha(1, \"Modo: Configuracao\");\n      escreverLinha(2, \"AP: \" + String(NOME_AP));\n    }\n    else if (WiFi.status() == WL_CONNECTED) {\n      escreverLinha(1, \"Status: Conectado\");\n      escreverLinha(2, \"Rede: \" + WiFi.SSID());\n    }\n    else {\n      escreverLinha(1, \"Status: Offline\");\n      escreverLinha(2, \"Reconectando sozinho\");\n    }\n\n    escreverLinha(3, \"A Prox.   * Voltar\");\n  }\n  else {\n    escreverLinha(0, \"STATUS DO WIFI  2/2\");\n\n    if (modoAPAtivo) {\n      escreverLinha(1, \"IP: 192.168.4.1\");\n      escreverLinha(2, \"Rede aberta\");\n      escreverLinha(3, \"B Voltar   * Menu\");\n    }\n    else if (WiFi.status() == WL_CONNECTED) {\n      escreverLinha(1, \"IP: \" + WiFi.localIP().toString());\n      escreverLinha(2, \"Pendentes: \" + String(contarPendentes()));\n      escreverLinha(3, \"A Config B Volt *M\");\n    }\n    else {\n      escreverLinha(1, \"Tentando reconectar\");\n      escreverLinha(2, \"A Configurar WiFi\");\n      escreverLinha(3, \"B Voltar   * Menu\");\n    }\n  }\n}\n\nvoid mostrarTelaAPConfiguracao() {\n  lcd.clear();\n  escreverLinha(0, \"CONFIGURAR WIFI\");\n  escreverLinha(1, String(\"Rede: \") + NOME_AP);\n  escreverLinha(2, \"Sem senha\");\n  escreverLinha(3, \"Acesse 192.168.4.1\");\n}\n\nbool processarResultadoComandoGlobalUI() {\n  if (!aguardandoComandoGlobalUI) {\n    return false;\n  }\n\n  // Enquanto a tarefa Firebase trabalha, bloqueia apenas novas teclas.\n  // Wi-Fi, LCD e tarefa de background continuam funcionando.\n  if (resultadoComandoGlobal == 0) {\n    return true;\n  }\n\n  int comandoFinalizado =\n    comandoGlobalUIAtual;\n\n  bool sucesso =\n    resultadoComandoGlobal == 1;\n\n  aguardandoComandoGlobalUI = false;\n  resultadoComandoGlobal = 0;\n  comandoGlobalUIAtual =\n    CMD_GLOBAL_NENHUM;\n\n  // Evita um redraw pendente sobrescrever a mensagem de sucesso.\n  atualizarInterfacePorControleGlobal = false;\n\n  lcd.clear();\n\n  if (!sucesso) {\n    escreverLinha(0, \"FALHA NA SINCRONIZ.\");\n    escreverLinha(1, \"Nada foi alterado\");\n    escreverLinha(2, \"Confira o Wi-Fi\");\n    escreverLinha(3, \"e tente novamente\");\n  }\n  else if (\n    comandoFinalizado ==\n    CMD_GLOBAL_ZERAR\n  ) {\n    escreverLinha(0, \"VOTACAO ZERADA\");\n    escreverLinha(1, \"Urnas + site\");\n    escreverLinha(2, \"Nova rodada ativa\");\n    escreverLinha(3, \"\");\n  }\n  else if (\n    comandoFinalizado ==\n    CMD_GLOBAL_ENCERRAR\n  ) {\n    escreverLinha(0, \"VOTACAO ENCERRADA\");\n    escreverLinha(1, \"Estado GLOBAL\");\n    escreverLinha(2, \"As 2 urnas seguem\");\n    escreverLinha(3, \"o Firebase\");\n  }\n  else {\n    escreverLinha(0, \"VOTACAO REABERTA\");\n    escreverLinha(1, \"Estado GLOBAL\");\n    escreverLinha(2, \"As 2 urnas seguem\");\n    escreverLinha(3, \"o Firebase\");\n  }\n\n  delay(2000);\n  mostrarMenuOperador();\n\n  return true;\n}\n\nvoid processarAtualizacaoInterfaceGlobal() {\n  if (!atualizarInterfacePorControleGlobal) {\n    return;\n  }\n\n  atualizarInterfacePorControleGlobal = false;\n\n  // Se outra urna zerou/encerrou enquanto um eleitor digitava,\n  // cancela a operacao em andamento para manter o estado coerente.\n  if (\n    estado == TELA_INICIAL ||\n    estado == DIGITAR_PROJETO ||\n    estado == CONFIRMAR_VOTO\n  ) {\n    numeroDigitado = \"\";\n    projetoSelecionado = nullptr;\n    mostrarTelaInicial();\n  }\n}\n\n// =====================================================\n// SETUP\n// =====================================================\n\nvoid setup() {\n  // Pequena estabilizacao de alimentacao para partida a frio.\n  // IMPORTANTE: a urna NAO espera computador, Arduino IDE ou Monitor Serial.\n  delay(300);\n\n  // Serial fica somente para diagnostico quando um computador estiver conectado.\n  // A inicializacao do sistema continua normalmente mesmo sem USB de dados.\n  Serial.begin(115200);\n\n  Serial.println();\n  Serial.println(\"========================================\");\n  Serial.println(\"URNA PET UFPB - V19.1 GLOBAL AUTONOMA\");\n  Serial.print(\"DISPOSITIVO: \");\n  Serial.println(ID_URNA);\n  Serial.println(\"========================================\");\n  delay(500);\n\n  Wire.begin(SDA_PIN, SCL_PIN);\n\n  lcd.init();\n  lcd.backlight();\n\n  mutexFila = xSemaphoreCreateMutex();\n  mutexDados = xSemaphoreCreateMutex();\n\n  if (!mutexFila || !mutexDados) {\n    Serial.println(\"ERRO: falha ao criar mutex do sistema.\");\n  }\n\n  iniciarLittleFS();\n  carregarMemoria();\n\n  lcd.clear();\n  escreverLinha(0, \"URNA PET UFPB\");\n  escreverLinha(1, \"\");\n  escreverLinha(2, \"Inicializando...\");\n  escreverLinha(3, \"Configurando Wi-Fi\");\n\n  iniciarSistemaWiFi();\n\n  delay(500);\n  mostrarTelaInicial();\n\n  // A partir daqui, HTTPS/Firebase nunca mais roda dentro do loop\n  // principal do teclado/LCD.\n  iniciarTarefaFirebase();\n}\n\n// =====================================================\n// LOOP\n// =====================================================\n\nvoid loop() {\n  // O loop principal cuida apenas de Wi-Fi leve + interface.\n  // HTTPS/Firebase roda em uma tarefa separada.\n  gerenciarWiFi();\n\n  // Resultado de comandos globais e mudancas vindas da outra urna\n  // sao tratados sem depender de Arduino IDE/Monitor Serial.\n  if (processarResultadoComandoGlobalUI()) {\n    return;\n  }\n\n  processarAtualizacaoInterfaceGlobal();\n\n  // Diagnostico periodico para o Monitor Serial nunca parecer\n  // completamente parado depois que as mensagens de boot passarem.\n  static unsigned long ultimoDiagnosticoSerial = 0;\n\n  if (\n    millis() - ultimoDiagnosticoSerial >= 5000\n  ) {\n    ultimoDiagnosticoSerial = millis();\n\n    Serial.print(\"[\");\n    Serial.print(ID_URNA);\n    Serial.print(\"] Sistema ativo | Wi-Fi: \");\n\n    if (WiFi.status() == WL_CONNECTED) {\n      Serial.print(\"CONECTADO | IP: \");\n      Serial.print(WiFi.localIP());\n    }\n    else {\n      Serial.print(\"DESCONECTADO | status=\");\n      Serial.print((int)WiFi.status());\n    }\n\n    Serial.print(\" | Tela=\");\n    Serial.print((int)estado);\n\n    Serial.print(\" | Rodada=\");\n    Serial.print(rodadaLocal);\n\n    Serial.print(\" | Pendentes=\");\n    Serial.println(contarPendentes());\n  }\n\n  char tecla = teclado.getKey();\n  if (!tecla) return;\n\n  // ---------------- TELA INICIAL ----------------\n  if (estado == TELA_INICIAL) {\n    if (tecla == '*') {\n      mostrarSenhaOperador();\n      return;\n    }\n\n    if (!votacaoAberta) return;\n\n    if (tecla == '1') {\n      cursoSelecionado = 1;\n      mostrarTelaProjeto();\n    }\n    else if (tecla == '2') {\n      cursoSelecionado = 2;\n      mostrarTelaProjeto();\n    }\n  }\n\n  // --------------- DIGITAR PROJETO --------------\n  else if (estado == DIGITAR_PROJETO) {\n    if (tecla >= '0' && tecla <= '9') {\n      if (numeroDigitado.length() < 2) {\n        numeroDigitado += tecla;\n        atualizarNumero();\n      }\n    }\n\n    else if (tecla == '*') {\n      if (numeroDigitado.length() > 0) {\n        numeroDigitado.remove(numeroDigitado.length() - 1);\n        atualizarNumero();\n      } else {\n        mostrarTelaInicial();\n      }\n    }\n\n    else if (tecla == '#') {\n      if (numeroDigitado.length() == 0) return;\n\n      int numero = numeroDigitado.toInt();\n\n      projetoSelecionado = buscarProjeto(\n        cursoSelecionado,\n        numero\n      );\n\n      if (projetoSelecionado == nullptr) {\n        lcd.clear();\n        escreverLinha(0, \"PROJETO INVALIDO\");\n        escreverLinha(1, \"\");\n        escreverLinha(2, \"Confira o numero\");\n        escreverLinha(3, \"Tente novamente\");\n        delay(1400);\n        mostrarTelaProjeto();\n      } else {\n        mostrarConfirmacao();\n      }\n    }\n  }\n\n  // --------------- CONFIRMAR VOTO ----------------\n  else if (estado == CONFIRMAR_VOTO) {\n    if (tecla == '#') {\n      registrarVoto();\n    }\n    else if (tecla == '*') {\n      mostrarTelaProjeto();\n    }\n  }\n\n  // --------------- SENHA OPERADOR ----------------\n  else if (estado == SENHA_OPERADOR) {\n    if (tecla >= '0' && tecla <= '9') {\n      if (senhaDigitada.length() < 8) {\n        senhaDigitada += tecla;\n\n        String estrelas = \"\";\n        for (int i = 0; i < senhaDigitada.length(); i++) {\n          estrelas += \"*\";\n        }\n\n        escreverLinha(2, \"Senha: \" + estrelas);\n      }\n    }\n\n    else if (tecla == '#') {\n      if (senhaDigitada == senhaOperador) {\n        paginaMenuOperador = 1;\n\n        lcd.clear();\n        escreverLinha(0, \"ACESSO LIBERADO\");\n        escreverLinha(1, \"\");\n        escreverLinha(2, \"Bem-vindo\");\n        escreverLinha(3, \"Modo operador\");\n\n        delay(800);\n        mostrarMenuOperador();\n      } else {\n        lcd.clear();\n        escreverLinha(0, \"SENHA INCORRETA\");\n        escreverLinha(1, \"\");\n        escreverLinha(2, \"Tente novamente\");\n        escreverLinha(3, \"\");\n        delay(1200);\n        mostrarSenhaOperador();\n      }\n    }\n\n    else if (tecla == '*') {\n      mostrarTelaInicial();\n    }\n  }\n\n  // --------------- MENU OPERADOR -----------------\n  else if (estado == MENU_OPERADOR) {\n    if (paginaMenuOperador == 1) {\n      if (tecla == '1') abrirTop3(1);\n      else if (tecla == '2') abrirTop3(2);\n      else if (tecla == 'A') {\n        paginaMenuOperador = 2;\n        mostrarMenuOperador();\n      }\n      else if (tecla == '*') {\n        mostrarTelaInicial();\n      }\n    }\n\n    else if (paginaMenuOperador == 2) {\n      if (tecla == '3') mostrarTotais();\n      else if (tecla == '4') pedirEncerrarOuReabrir();\n      else if (tecla == 'A') {\n        paginaMenuOperador = 3;\n        mostrarMenuOperador();\n      }\n      else if (tecla == 'B') {\n        paginaMenuOperador = 1;\n        mostrarMenuOperador();\n      }\n      else if (tecla == '*') {\n        mostrarTelaInicial();\n      }\n    }\n\n    else if (paginaMenuOperador == 3) {\n      if (tecla == '5') pedirSenhaZerar();\n      else if (tecla == '6') {\n        paginaStatusWiFi = 1;\n        mostrarStatusWiFi();\n      }\n      else if (tecla == 'B') {\n        paginaMenuOperador = 2;\n        mostrarMenuOperador();\n      }\n      else if (tecla == '*') {\n        mostrarTelaInicial();\n      }\n    }\n  }\n\n  // ---------------- STATUS WIFI -------------------\n  else if (estado == STATUS_WIFI) {\n    if (tecla == '*') {\n      mostrarMenuOperador();\n    }\n\n    else if (\n      paginaStatusWiFi == 1 &&\n      tecla == 'A'\n    ) {\n      paginaStatusWiFi = 2;\n      mostrarStatusWiFi();\n    }\n\n    else if (\n      paginaStatusWiFi == 2 &&\n      tecla == 'B'\n    ) {\n      paginaStatusWiFi = 1;\n      mostrarStatusWiFi();\n    }\n\n    // A na pagina 2 entra deliberadamente em modo de configuracao.\n    // Isso desliga o STA e cria SOMENTE o AP.\n    else if (\n      paginaStatusWiFi == 2 &&\n      tecla == 'A' &&\n      !modoAPAtivo\n    ) {\n      iniciarModoConfiguracaoAP();\n      mostrarTelaAPConfiguracao();\n\n      delay(3500);\n\n      paginaStatusWiFi = 1;\n      mostrarStatusWiFi();\n    }\n  }\n\n  // ------------- RESULTADO NAVEGAVEL -------------\n  else if (estado == RESULTADO_NAVEGAVEL) {\n    if (tecla == '*') {\n      mostrarMenuOperador();\n    }\n    else if (quantidadeRanking > 0 && tecla == 'A') {\n      indiceRanking++;\n\n      if (indiceRanking >= quantidadeRanking) {\n        indiceRanking = 0;\n      }\n\n      mostrarResultadoAtual();\n    }\n    else if (quantidadeRanking > 0 && tecla == 'B') {\n      indiceRanking--;\n\n      if (indiceRanking < 0) {\n        indiceRanking = quantidadeRanking - 1;\n      }\n\n      mostrarResultadoAtual();\n    }\n  }\n\n  // --------------- SENHA PARA ZERAR --------------\n  else if (estado == SENHA_ZERAR) {\n    if (tecla >= '0' && tecla <= '9') {\n      if (senhaDigitada.length() < 8) {\n        senhaDigitada += tecla;\n\n        String estrelas = \"\";\n        for (int i = 0; i < senhaDigitada.length(); i++) {\n          estrelas += \"*\";\n        }\n\n        escreverLinha(2, \"Senha: \" + estrelas);\n      }\n    }\n    else if (tecla == '#') {\n      if (senhaDigitada == senhaOperador) {\n        pedirZerar();\n      } else {\n        lcd.clear();\n        escreverLinha(0, \"SENHA INCORRETA\");\n        escreverLinha(1, \"\");\n        escreverLinha(2, \"Operacao cancelada\");\n        escreverLinha(3, \"\");\n        delay(1200);\n        mostrarMenuOperador();\n      }\n    }\n    else if (tecla == '*') {\n      mostrarMenuOperador();\n    }\n  }\n\n  // --------------- ENCERRAR -----------------------\n  else if (estado == CONFIRMAR_ENCERRAR) {\n    if (tecla == '#') {\n      iniciarSolicitacaoComandoGlobal(\n        CMD_GLOBAL_ENCERRAR,\n        \"ENCERRANDO VOTACAO\"\n      );\n    }\n    else if (tecla == '*') {\n      mostrarMenuOperador();\n    }\n  }\n\n  // --------------- REABRIR ------------------------\n  else if (estado == CONFIRMAR_REABRIR) {\n    if (tecla == '#') {\n      iniciarSolicitacaoComandoGlobal(\n        CMD_GLOBAL_REABRIR,\n        \"REABRINDO VOTACAO\"\n      );\n    }\n    else if (tecla == '*') {\n      mostrarMenuOperador();\n    }\n  }\n\n  // ---------------- ZERAR --------------------------\n  else if (estado == CONFIRMAR_ZERAR) {\n    if (tecla == '#') {\n      executarZerar();\n    }\n    else if (tecla == '*') {\n      mostrarMenuOperador();\n    }\n  }\n}";
